-- Speaking library v2: multi-level items, student-safe presenter content, and reusable seed catalogue.

alter table public.admin_speaking_activities
  add column if not exists student_intro text,
  add column if not exists student_steps jsonb not null default '[]'::jsonb,
  add column if not exists useful_language jsonb not null default '[]'::jsonb,
  add column if not exists presenter_style text not null default 'prompt';

alter table public.admin_speaking_activities
  drop constraint if exists admin_speaking_activities_student_steps_array,
  drop constraint if exists admin_speaking_activities_useful_language_array,
  drop constraint if exists admin_speaking_activities_presenter_style_check;

alter table public.admin_speaking_activities
  add constraint admin_speaking_activities_student_steps_array check (jsonb_typeof(student_steps) = 'array'),
  add constraint admin_speaking_activities_useful_language_array check (jsonb_typeof(useful_language) = 'array'),
  add constraint admin_speaking_activities_presenter_style_check
    check (presenter_style in ('prompt','choice','odd_one_out','repair','taboo','story','ranking','roleplay'));

update public.admin_speaking_activities activity
set prompts = (
  select coalesce(
    jsonb_agg(
      case
        when jsonb_typeof(entry.value) = 'string' then jsonb_build_object(
          'text', entry.value #>> '{}',
          'levels', to_jsonb(activity.levels),
          'student_support', '',
          'challenge', '',
          'teacher_note', ''
        )
        else entry.value
      end
      order by entry.ordinality
    ),
    '[]'::jsonb
  )
  from jsonb_array_elements(activity.prompts) with ordinality entry(value, ordinality)
)
where exists (
  select 1
  from jsonb_array_elements(activity.prompts) entry(value)
  where jsonb_typeof(entry.value) = 'string'
);

create temporary table speaking_activity_seed(payload jsonb);
insert into speaking_activity_seed(payload) values ('[{"tags":["conversation","critical thinking"],"goals":["opinions","nuance","extended answers"],"title":"Agree, Disagree, It Depends","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"People should never work during their holidays.","levels":["A2","B1"],"challenge":"Give one exception to your position.","teacher_note":"Push beyond yes/no: require because + example.","student_support":"Think about rest, emergencies and different jobs."},{"text":"Being good at your job is more important than enjoying it.","levels":["B1","B2","C1"],"challenge":"Now argue the opposite side for 30 seconds.","teacher_note":"Good for hedging: to some extent, in the long run.","student_support":"Think about motivation, salary and long-term satisfaction."},{"text":"Social media makes friendships weaker.","levels":["A2","B1","B2"],"challenge":"Name one situation where the opposite is true.","teacher_note":"","student_support":"Think about distance, attention and communication."},{"text":"A four-day working week would improve most companies.","levels":["B2","C1"],"challenge":"What kind of company might struggle with it?","teacher_note":"Useful for qualifiers and exceptions.","student_support":"Think about productivity, customers and workload."}],"summary":"Opinion prompts where “it depends” only counts if the learner explains exactly what it depends on.","favorite":false,"variants":["Fast version: 45 seconds per statement.","No neutral answer: ban “it depends” for one round.","C1: require one counterargument before concluding."],"group_size":"1–6","instructions":"Show one statement. The learner chooses Agree, Disagree or It depends, then supports the choice with reasons and examples.","activity_type":"conversation","student_intro":"Choose Agree, Disagree or It depends — then make your position convincing.","student_steps":["Choose your position.","Give a reason.","Add an example.","Respond to the challenge."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I tend to agree because…","I’m not completely convinced that…","It depends on…","One exception would be…"],"duration_minutes":15},{"tags":["fun","creative"],"goals":["fluency","modals","advice"],"title":"Bad Advice Only","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"I have an important interview tomorrow and I haven’t prepared.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"My colleague keeps interrupting me in meetings.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I’m always late because I snooze my alarm five times.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I need to improve my English but I hate studying grammar books.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I accidentally sent a private message to the wrong person.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Lo studente deve dare intenzionalmente il peggior consiglio possibile, poi correggerlo con una soluzione reale.","favorite":true,"variants":["B1+: obbliga a usare should / shouldn’t / if I were you.","Business version: solo problemi di lavoro.","Follow-up: tu difendi il cattivo consiglio e lo studente deve convincerti."],"group_size":"1–5","instructions":"Presenta un problema. Prima lo studente dà un consiglio assurdo o pessimo. Poi deve spiegare perché sarebbe una cattiva idea e proporre un consiglio vero.","activity_type":"speaking_game","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":12},{"tags":["small-talk","analysis"],"goals":["small talk","follow-up","conversation management"],"title":"Bad Small Talk / Good Small Talk","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"BAD:\nA: Did you have a good weekend?\nB: Yes.\nA: Okay.\nGOOD:\nA: Did you have a good weekend?\nB: Yeah, I went hiking for the first time in months.\nA: Oh nice — where did you go?","levels":["A2","B1"],"challenge":"Continue the GOOD version for four more turns.","difficulty":2,"context_tags":["social","small-talk"],"teacher_note":"Core small-talk pattern: answer + detail + follow-up.","student_support":"Notice answer length and connected follow-up.","language_targets":["extended-answer","follow-up"]},{"text":"BAD:\nA: What do you do?\nB: I’m an engineer.\nA: Do you like sports?\nGOOD:\nA: What do you do?\nB: I’m an engineer.\nA: What kind of projects do you work on?","levels":["A2","B1"],"challenge":"Repair the BAD dialogue without changing the first question.","difficulty":2,"context_tags":["work","small-talk"],"teacher_note":"Topic development.","student_support":"Why does the first version feel like an interview checklist?","language_targets":["topic-development","questions"]},{"text":"BAD:\nA: I’ve just moved here.\nB: Ah.\nGOOD:\nA: I’ve just moved here.\nB: Oh really? How are you finding it so far?","levels":["A2","B1","B2"],"challenge":"Add a brief personal connection after the answer.","difficulty":3,"context_tags":["social","moving"],"teacher_note":"Teach react → explore → relate.","student_support":"Reaction + question.","language_targets":["reactions","self-disclosure"]},{"text":"BAD:\nA: Work has been intense lately.\nB: You should organise your time better.\nGOOD:\nA: Work has been intense lately.\nB: That sounds exhausting. Is it one project or just everything at once?","levels":["B1","B2"],"challenge":"Continue without giving advice for three turns.","difficulty":3,"context_tags":["work","relationships"],"teacher_note":"Supportive conversation skill.","student_support":"Notice advice vs empathy/exploration.","language_targets":["empathy","follow-up"]}],"summary":"Compare two short conversations and identify why one dies while the other develops naturally.","favorite":true,"variants":["Learner labels the exact move that improves flow.","Hide GOOD version and repair first.","Teacher plays deliberately bad small talk."],"group_size":"1–4","instructions":"Show two mini-dialogues. Learner identifies what helps/hurts flow, repairs the weak version, then continues.","activity_type":"conversation","student_intro":"One conversation dies. One continues. Find the difference and improve the weak one.","student_steps":["Compare the dialogues.","Identify the conversation move.","Repair the weak version.","Continue naturally."],"teacher_notes":null,"presenter_style":"repair","useful_language":["The problem is that…","A better follow-up would be…","They could react first by saying…","That keeps the topic going because…"],"duration_minutes":15},{"tags":["sequence","real-life"],"goals":["sequencing","functional language","planning"],"title":"Before / During / After","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"A job interview","levels":["A2","B1","B2"],"challenge":"Add one thing people often forget.","difficulty":3,"context_tags":["work","interview"],"teacher_note":"Great professional functional speaking.","student_support":"Before: prepare. During: communicate. After: follow up.","language_targets":["sequencing","advice"]},{"text":"Taking an international flight","levels":["A1","A2"],"challenge":"Something goes wrong during the journey.","difficulty":1,"context_tags":["travel","airport"],"teacher_note":"Travel basics.","student_support":"Before airport → at airport → after arrival.","language_targets":["sequence","travel-language"]},{"text":"Giving a presentation at work","levels":["B1","B2"],"challenge":"You realise halfway through that you are running out of time.","difficulty":3,"context_tags":["work","presentation"],"teacher_note":"Presentation language.","student_support":"Preparation, delivery, questions, follow-up.","language_targets":["sequencing","problem-solving"]},{"text":"Moving to a new city","levels":["A2","B1","B2"],"challenge":"You know nobody there.","difficulty":2,"context_tags":["life","moving"],"teacher_note":"Future/planning.","student_support":"Plan before, first week, first month.","language_targets":["future","planning"]}],"summary":"Organise speaking around an event across preparation, experience and follow-up.","favorite":false,"variants":["Advice to someone else.","Past version: what actually happened.","Random complication in the During stage."],"group_size":"1–4","instructions":"Give an event. Learner explains what to do before, during and after, with level-appropriate detail.","activity_type":"conversation","student_intro":"Think through the whole experience: what matters before, during and after?","student_steps":["Plan the ‘before’.","Describe the key actions during.","Explain the follow-up.","Handle the extra complication."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["Beforehand…","Once I’m there…","During the…","Afterwards…","The first thing I’d do is…"],"duration_minutes":15},{"tags":["design","choices"],"goals":["describing","preferences","justification"],"title":"Build the Perfect...","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"Build the perfect weekend.","levels":["A1","A2"],"challenge":"You only have €50.","difficulty":1,"context_tags":["daily-life","leisure"],"teacher_note":"A1: support with I want / I’d like / because.","student_support":"Choose place, people, food and one activity.","language_targets":["preferences","because"]},{"text":"Build the perfect city to live in.","levels":["A2","B1"],"challenge":"You must sacrifice one thing you chose.","difficulty":2,"context_tags":["city","lifestyle"],"teacher_note":"Good for comparatives.","student_support":"Think about size, transport, weather, jobs and cost.","language_targets":["comparatives","priorities"]},{"text":"Build the perfect manager.","levels":["B1","B2"],"challenge":"The team is under serious deadline pressure.","difficulty":3,"context_tags":["work","management"],"teacher_note":"Push specific behaviours, not adjectives only.","student_support":"Choose communication style, autonomy, feedback and expectations.","language_targets":["describing-behaviour","workplace"]},{"text":"Build the perfect holiday for two people who want completely different things.","levels":["B1","B2"],"challenge":"Agree on only three priorities.","difficulty":3,"context_tags":["travel","relationships"],"teacher_note":"Negotiation language.","student_support":"One wants adventure; one wants rest.","language_targets":["negotiation","compromise"]}],"summary":"Design the ideal version of something by choosing priorities and defending them.","favorite":false,"variants":["Give a fixed budget.","Force one unpopular compromise.","Compare final designs between learners."],"group_size":"1–6","instructions":"Give a category. Learner chooses features one by one, explains priorities, then deals with one constraint.","activity_type":"conversation","student_intro":"Create your ideal version — but be ready to explain every choice.","student_steps":["Choose your priorities.","Explain why each matters.","Add specific details.","Adapt when a constraint appears."],"teacher_notes":null,"presenter_style":"ranking","useful_language":["For me, the most important thing is…","I’d definitely include…","I could compromise on…","If I had to choose, I’d keep…"],"duration_minutes":15},{"tags":["debate","persuasion"],"goals":["persuasion","argumentation","rebuttal"],"title":"Change My Mind","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"I think remote work makes teams less effective.","levels":["B1","B2"],"challenge":"I say: ‘Communication is always slower online.’","difficulty":3,"context_tags":["work","remote-work"],"teacher_note":"Reward direct response to objection, not a new unrelated point.","student_support":"Choose your strongest reason first.","language_targets":["persuasion","rebuttal"]},{"text":"I think travelling alone is a bad idea.","levels":["B1","B2"],"challenge":"I say: ‘You have nobody to help if something goes wrong.’","difficulty":3,"context_tags":["travel"],"teacher_note":"Good for concession + rebuttal.","student_support":"Think about safety, freedom and confidence.","language_targets":["concession","rebuttal"]},{"text":"I think university is necessary for a successful career.","levels":["B2","C1"],"challenge":"I say: ‘Employers still trust degrees more than self-study.’","difficulty":4,"context_tags":["education","career"],"teacher_note":"Push evidence/examples without overclaiming.","student_support":"Distinguish between professions and career paths.","language_targets":["qualification","argumentation"]},{"text":"I think people should always reply to messages quickly.","levels":["B1","B2","C1"],"challenge":"I say: ‘Ignoring messages is disrespectful.’","difficulty":3,"context_tags":["communication","boundaries"],"teacher_note":"Useful for defining exceptions.","student_support":"Think about urgency, boundaries and context.","language_targets":["nuance","persuasion"]}],"summary":"The learner has a limited number of arguments to persuade the other person to reconsider.","favorite":false,"variants":["Only two arguments allowed.","Switch sides after round one.","Require one concession before the final argument."],"group_size":"1–4","instructions":"Give a position. The learner gets three arguments. After each, respond with an objection. Then switch roles.","activity_type":"debate","student_intro":"You have three chances to make me reconsider my position.","student_steps":["Listen to the position.","Choose your strongest argument.","Respond to the objection.","Finish with your best final point."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["I see why you think that, but…","The bigger issue is…","That’s true in some cases; however…","What might change your mind is…"],"duration_minutes":15},{"tags":["detective","dialogue"],"goals":["inference","storytelling","pragmatics"],"title":"Conversation Detective","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"A: Did you tell her?\nB: Not yet.\nA: You can’t keep avoiding it.","levels":["A2","B1"],"challenge":"Create the next two lines.","difficulty":2,"context_tags":["relationships","story"],"teacher_note":"No single answer; coherence matters.","student_support":"Who are they? What information is being avoided?","language_targets":["inference","dialogue"]},{"text":"A: I thought you said Thursday.\nB: I did. Next Thursday.\nA: You’re joking.","levels":["A2","B1","B2"],"challenge":"Create the message that caused the misunderstanding.","difficulty":3,"context_tags":["plans","communication"],"teacher_note":"Time reference ambiguity.","student_support":"What arrangement was misunderstood?","language_targets":["misunderstanding","storytelling"]},{"text":"A: They accepted it.\nB: All of it?\nA: Except the last condition.","levels":["B1","B2"],"challenge":"Decide what the last condition was and why it failed.","difficulty":4,"context_tags":["work","negotiation"],"teacher_note":"Work/negotiation possibilities.","student_support":"What kind of agreement could this be?","language_targets":["inference","speculation"]},{"text":"A: He said it was ‘interesting’.\nB: Oh no.\nA: Exactly.","levels":["B2","C1"],"challenge":"Build the five lines before this moment.","difficulty":5,"context_tags":["work","pragmatics"],"teacher_note":"Pragmatic inference.","student_support":"Why can ‘interesting’ be bad news here?","language_targets":["implicature","storytelling"]}],"summary":"Reconstruct relationship, setting and backstory from a tiny fragment of dialogue.","favorite":true,"variants":["Multiple hypotheses before choosing.","Teacher reveals one extra clue after first theory.","Retell complete scene from one character’s perspective."],"group_size":"1–4","instructions":"Show only a short dialogue fragment. Learner infers who, where, what happened before and what is likely next.","activity_type":"speaking_game","student_intro":"You only get a few lines. Reconstruct the conversation around them.","student_steps":["Infer the relationship.","Guess what happened before.","Explain your evidence.","Continue the scene."],"teacher_notes":null,"presenter_style":"story","useful_language":["It sounds as if…","My guess is that…","The clue is…","What probably happened before was…"],"duration_minutes":18},{"tags":["branching","small-talk"],"goals":["conversation strategy","follow-up","topic development"],"title":"Conversation Fork","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"They say: “I’ve just started a new job.”\nChoose a direction:\nA) Ask about the role\nB) Ask how they feel about the change\nC) Connect it to your own experience","levels":["A2","B1"],"challenge":"After two turns, switch naturally to another branch.","difficulty":2,"context_tags":["work","small-talk"],"teacher_note":"Teaches strategic topic development.","student_support":"All can work; choose based on what kind of conversation you want.","language_targets":["follow-up","topic-development"]},{"text":"They say: “My flight was cancelled yesterday.”\nA) Ask what happened next\nB) React emotionally\nC) Ask about the airline/solution","levels":["A2","B1","B2"],"challenge":"Do not turn it into an interview.","difficulty":3,"context_tags":["travel","conversation"],"teacher_note":"Reaction + exploration.","student_support":"Choose one move, then keep going.","language_targets":["reactions","follow-up"]},{"text":"A colleague says: “I’m not convinced by the new process.”\nA) Ask for specific concerns\nB) Defend the process\nC) Ask what alternative they prefer","levels":["B1","B2"],"challenge":"Switch branch after new information.","difficulty":4,"context_tags":["work","discussion"],"teacher_note":"Work conversation strategy.","student_support":"Think about what outcome each branch creates.","language_targets":["clarification","strategy"]},{"text":"A client says: “We need to think about it.”\nA) Ask about concerns\nB) clarify next steps\nC) restate value","levels":["B2","C1"],"challenge":"Explain why another branch could backfire.","difficulty":5,"context_tags":["work","client"],"teacher_note":"Negotiation pragmatics.","student_support":"Choose based on whether the hesitation sounds substantive or procedural.","language_targets":["negotiation","conversation-strategy"]}],"summary":"Choose how a conversation develops by selecting one of several plausible next moves.","favorite":true,"variants":["Teacher chooses branch secretly; learner predicts.","Branch twice in one conversation.","Rank options before roleplay."],"group_size":"1–4","instructions":"Show a line plus three possible conversation directions. Learner chooses one, explains, then improvises that branch.","activity_type":"conversation","student_intro":"There is more than one way to continue. Choose the direction that best fits your goal.","student_steps":["Read the last line.","Choose a direction.","Explain what that move achieves.","Continue the conversation."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I’d go with… because…","That opens the conversation by…","A natural follow-up would be…","From there, I’d move to…"],"duration_minutes":18},{"tags":["warm-up","low prep"],"goals":["fluency","follow-up questions","confidence"],"title":"Conversation Roulette","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"What is something you used to dislike but now enjoy?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"What makes a place feel comfortable to you?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"What is one small decision that improved your daily life?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"What is something people often misunderstand about your job or studies?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"If you had one extra free hour every day, how would you use it?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"Which skill is more useful than people think?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Rapid speaking rounds: answer, extend, then ask a follow-up.","favorite":true,"variants":["Speed round: 20 seconds only.","Depth round: ask Why? three times.","No-safe-answer round: ban yes/no openings."],"group_size":"1–4","instructions":"Answer for at least 30 seconds. Add one detail that was not asked for. Finish by asking a related question back.","activity_type":"conversation","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":12},{"tags":["sales","argument"],"goals":["persuasion","fluency","functional language"],"title":"Convince Me","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Convince me to wake up at 5:00 every day.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Convince me that meetings are useful.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Sell me a holiday in a place where it rains every day.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Convince me to delete all social media for one month.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Sell me a very expensive notebook with no special technology.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Lo studente deve venderti o difendere qualcosa di poco attraente usando argomenti sempre più forti.","favorite":true,"variants":["Business English: usa objection-handling chunks.","C1: dopo due minuti, cambia improvvisamente target audience.","Vocabulary: assegna tre chunks obbligatori da integrare."],"group_size":"1–3","instructions":"Dai un oggetto, un’idea o una posizione difficile da vendere. Tu opponi 2–3 obiezioni reali. Lo studente deve rispondere senza ripetere lo stesso argomento.","activity_type":"debate","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":15},{"tags":["debate","opinions"],"goals":["argumentation","hedging","spontaneous speaking"],"title":"Defend the Opposite","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Working from home is better than working in an office.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"University is still the best route to a good career.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"People should answer work messages outside working hours.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"It is better to be extremely organised than spontaneous.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Artificial intelligence makes people less creative.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Argue for the position you would not normally choose.","favorite":true,"variants":["Ban good, bad, better and worse.","Add a 30-second rebuttal.","Require one softener such as arguably or to some extent."],"group_size":"1–4","instructions":"Give your real opinion first. Then defend the opposite side for 60–90 seconds using at least two reasons and one example.","activity_type":"debate","student_intro":"First give your real opinion. Then switch sides and make the opposite position sound convincing.","student_steps":["State your real opinion briefly.","Defend the opposite view.","Give two reasons and one example.","Finish with a concession."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["From another perspective…","One advantage is that…","That might be true, but…","A good example would be…","To some extent…"],"duration_minutes":15},{"tags":["description","constraints"],"goals":["description","precision","fluency"],"title":"Describe Without Adjectives","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Describe a place you love — no adjectives.","levels":["A2","B1"],"challenge":"Make me guess the place type.","difficulty":2,"context_tags":["places","personal"],"teacher_note":"Actions/details over labels.","student_support":"Say what you see, hear, do and how people behave there.","language_targets":["description","sensory-detail"]},{"text":"Describe a person you trust — no personality adjectives.","levels":["A2","B1","B2"],"challenge":"Give one specific example.","difficulty":3,"context_tags":["relationships","people"],"teacher_note":"Behavioural description.","student_support":"Tell me what they do that creates trust.","language_targets":["description","examples"]},{"text":"Describe a stressful work situation — no emotion adjectives.","levels":["B1","B2"],"challenge":"Make the listener feel the pressure through details.","difficulty":3,"context_tags":["work","story"],"teacher_note":"Narrative precision.","student_support":"Describe workload, timing, reactions and consequences.","language_targets":["description","narrative"]},{"text":"Describe an excellent leader — no evaluative adjectives.","levels":["B2","C1"],"challenge":"Include one behaviour that could become a weakness in excess.","difficulty":4,"context_tags":["work","leadership"],"teacher_note":"Advanced behavioural language.","student_support":"Describe decisions, communication and behaviour.","language_targets":["description","nuance"]}],"summary":"Describe people, places and experiences through actions, examples and sensory detail instead of adjective labels.","favorite":false,"variants":["Guessing game.","Ban adverbs too for advanced learners.","Afterward, choose the best adjective supported by evidence."],"group_size":"1–4","instructions":"Learner describes target without relying on adjectives. If an adjective appears, ask for evidence/behaviour instead.","activity_type":"vocabulary","student_intro":"Do not label it. Make us understand through actions, examples and details.","student_steps":["Choose concrete details.","Describe behaviour or events.","Give an example.","Let the listener infer the adjective."],"teacher_notes":null,"presenter_style":"taboo","useful_language":["They’re the kind of person who…","What usually happens is…","One example is…","You can tell because…"],"duration_minutes":15},{"tags":["warm-up","constraints"],"goals":["extended answers","fluency","rephrasing"],"title":"Don’t Say Yes","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"Do you usually eat breakfast?","levels":["A1","A2"],"challenge":"No yes/no.","difficulty":1,"context_tags":["daily-life","food"],"teacher_note":"Example: Most days I do, especially when…","student_support":"Answer with frequency or routine.","language_targets":["frequency","extended-answer"]},{"text":"Would you like to live in another country?","levels":["A2","B1"],"challenge":"No yes/no and no ‘maybe’ alone.","difficulty":2,"context_tags":["travel","life"],"teacher_note":"Conditionals.","student_support":"Give a condition or preference.","language_targets":["preferences","conditionals"]},{"text":"Is social media useful for you?","levels":["A2","B1","B2"],"challenge":"Give a balanced answer in two sentences.","difficulty":2,"context_tags":["technology","daily-life"],"teacher_note":"Nuance.","student_support":"Separate different uses.","language_targets":["nuance","extended-answer"]},{"text":"Do you think your current routine is sustainable?","levels":["B1","B2"],"challenge":"Use one contrast linker.","difficulty":3,"context_tags":["daily-life","wellbeing"],"teacher_note":"Push beyond binary.","student_support":"Explain what works and what does not.","language_targets":["contrast","evaluation"]}],"summary":"Answer ordinary questions without using yes, no or I don’t know, forcing fuller responses.","favorite":false,"variants":["Also ban ‘maybe’.","Five-second response limit.","Teacher tries to trick learner into yes/no."],"group_size":"1–6","instructions":"Ask quick questions. Learner may not say yes, no or I don’t know. Short substitutes alone do not count; answer must add meaning.","activity_type":"warmup","student_intro":"Answer naturally — but you cannot use yes, no or I don’t know.","student_steps":["Listen carefully.","Avoid the forbidden answers.","Give useful information.","Keep the conversation moving."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["Most of the time…","Not really, because…","I’d say…","It depends on…","I haven’t decided yet, but…"],"duration_minutes":10},{"tags":["travel","real-life","pressure"],"goals":["functional language","clarification","problem solving"],"title":"Emergency English","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"Your suitcase did not arrive at baggage claim.","levels":["A2","B1"],"challenge":"You need medication from the suitcase tonight.","difficulty":2,"context_tags":["travel","airport"],"teacher_note":"Target lost luggage language and urgency.","student_support":"Give flight details, describe the bag and ask what happens next.","language_targets":["problem-reporting","requests"]},{"text":"You missed the last train because your first train was delayed.","levels":["A2","B1"],"challenge":"The ticket office says your ticket is not valid on the bus replacement.","difficulty":3,"context_tags":["travel","transport"],"teacher_note":"Push clarification.","student_support":"Explain the connection and ask about alternatives.","language_targets":["clarification","negotiation"]},{"text":"The hotel has no record of your prepaid reservation.","levels":["A2","B1","B2"],"challenge":"The hotel is fully booked.","difficulty":3,"context_tags":["travel","hotel"],"teacher_note":"Outcome focus: alternative room/refund/support.","student_support":"Show what information you have and ask them to check.","language_targets":["complaints","problem-solving"]},{"text":"You are abroad and your bank card is suddenly blocked.","levels":["B1","B2"],"challenge":"The bank cannot verify your identity using the normal method.","difficulty":4,"context_tags":["travel","finance"],"teacher_note":"Keep safe/general; language task only.","student_support":"Explain what happened and what you need access to.","language_targets":["explaining-problems","clarification"]}],"summary":"High-pressure everyday situations where the learner must get a practical result.","favorite":true,"variants":["Add a 60-second timer.","Replay with a less cooperative staff member.","Learner summarizes the final solution at the end."],"group_size":"1–2","instructions":"Run short escalating roleplays. Learner must explain the problem, ask for action and react to complications.","activity_type":"roleplay","student_intro":"Something has gone wrong. Stay clear, calm and practical.","student_steps":["Explain the problem.","Give the key facts.","Ask for a specific solution.","React to the complication."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["I’m afraid there’s a problem with…","Could you check that for me?","What are my options?","I need to find a solution today because…"],"duration_minutes":20},{"tags":["taboo","retrieval"],"goals":["vocabulary","paraphrasing","fluency"],"title":"Explain It Without Saying It","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"deadline | forbidden: time, finish, date","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"overwhelmed | forbidden: stress, busy, too much","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"run out of | forbidden: finish, none, empty","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"reschedule | forbidden: change, meeting, time","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"reliable | forbidden: trust, person, always","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Descrivi una parola o un chunk senza usare le parole vietate; l’altro deve indovinare.","favorite":false,"variants":["Per chunk: dopo l’indovinello, chiedi una collocation naturale.","A2: una sola parola vietata.","C1: richiedi definizione + esempio + contrasto con un termine simile."],"group_size":"1–6","instructions":"Scegli un target e 2–4 parole vietate. Chi descrive non può tradurre né mimare. Dopo che il target viene indovinato, deve essere usato in una frase personale o professionale.","activity_type":"vocabulary","student_intro":"Explain the target without saying the target itself or the forbidden words.","student_steps":["Describe the meaning.","Give an example or situation.","Keep talking until the other person guesses.","Use the target naturally after it is guessed."],"teacher_notes":null,"presenter_style":"taboo","useful_language":["It’s something you…","You use it when…","It’s similar to…, but…","For example…","The opposite would be…"],"duration_minutes":15},{"tags":["vocabulary","contrast"],"goals":["vocabulary precision","examples","paraphrasing"],"title":"Explain the Difference","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"trip vs journey","levels":["A2","B1"],"challenge":"Use both naturally in one short story.","difficulty":2,"context_tags":["travel","vocabulary"],"teacher_note":"Keep definitions practical, not dictionary-like.","student_support":"Think about the whole experience vs movement from one place to another.","language_targets":["lexical-contrast","examples"]},{"text":"job vs work","levels":["A2","B1"],"challenge":"Create three sentences where only one fits naturally.","difficulty":2,"context_tags":["work","vocabulary"],"teacher_note":"Watch countability/collocation.","student_support":"One can be a position; one is broader activity/effort.","language_targets":["lexical-contrast","collocations"]},{"text":"confident vs arrogant","levels":["B1","B2"],"challenge":"Describe someone who seems confident but not arrogant.","difficulty":3,"context_tags":["personality","work"],"teacher_note":"Connotation.","student_support":"Focus on behaviour and how other people perceive it.","language_targets":["connotation","description"]},{"text":"efficient vs effective","levels":["B2","C1"],"challenge":"Give a process that is efficient but not effective.","difficulty":4,"context_tags":["work","business"],"teacher_note":"Excellent business distinction.","student_support":"Think about resources used vs result achieved.","language_targets":["precision","examples"]}],"summary":"Explain the difference between close words or concepts, then prove it with contexts.","favorite":true,"variants":["Learner proposes the pair.","Ban direct definitions; examples only.","Add a third related word."],"group_size":"1–4","instructions":"Show a pair. Learner explains the difference without translating first, then gives one context for each.","activity_type":"vocabulary","student_intro":"These words are close, but not identical. Explain the difference so another learner could actually use them.","student_steps":["Describe the difference.","Give one example for each.","Compare the typical context.","Use both naturally."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["They’re similar, but…","You’d usually use ___ when…","The difference is mainly…","For example…"],"duration_minutes":15},{"tags":["persuasion","audience"],"goals":["perspective taking","persuasion","adaptation"],"title":"Explain Your Choice to Someone Who Disagrees","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"You choose a more expensive apartment because it is central.\nExplain it to someone who cares mainly about saving money.","levels":["B1","B2"],"challenge":"You cannot say ‘because I prefer it’.","difficulty":3,"context_tags":["housing","money"],"teacher_note":"Audience adaptation.","student_support":"Translate your priority into something they value.","language_targets":["persuasion","reframing"]},{"text":"You want to change jobs for a more interesting role.\nExplain it to someone who values stability above everything.","levels":["B1","B2"],"challenge":"Give one concrete risk-control measure.","difficulty":4,"context_tags":["work","career"],"teacher_note":"Concession + reframing.","student_support":"Acknowledge risk before defending the move.","language_targets":["persuasion","concession"]},{"text":"You want your team to experiment with a new tool.\nExplain it to a manager who hates disruption.","levels":["B2","C1"],"challenge":"They ask what happens if adoption fails.","difficulty":5,"context_tags":["work","technology"],"teacher_note":"Business stakeholder communication.","student_support":"Focus on controlled testing and downside protection.","language_targets":["stakeholder-language","risk"]},{"text":"You choose a slower but more sustainable travel option.\nExplain it to someone who values convenience.","levels":["B1","B2","C1"],"challenge":"Offer a compromise.","difficulty":4,"context_tags":["travel","values"],"teacher_note":"Perspective shift.","student_support":"Do not assume they share your values.","language_targets":["persuasion","compromise"]}],"summary":"Adapt an explanation to a listener with different priorities instead of simply repeating the same argument.","favorite":false,"variants":["Audience changes halfway through.","Learner identifies audience value before speaking.","Repeat with opposite framing."],"group_size":"1–4","instructions":"Learner makes a choice, then receives an audience profile that values something different. They must reframe the explanation.","activity_type":"debate","student_intro":"A strong explanation changes depending on who is listening.","student_steps":["Make your choice.","Identify the listener’s priority.","Reframe your reasons.","Answer their objection."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["I know your main concern is…","From your perspective…","The reason this could still make sense is…","A compromise would be…"],"duration_minutes":18},{"tags":["sentence-stems","conversation"],"goals":["fluency","personalisation","complex sentences"],"title":"Finish My Thought","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"I knew it was a bad idea when…","levels":["A2","B1"],"challenge":"Continue for at least three sentences.","difficulty":2,"context_tags":["personal","story"],"teacher_note":"Past narrative.","student_support":"Tell a real or invented short story.","language_targets":["past-simple","storytelling"]},{"text":"One thing I wish people understood about my job/studies is…","levels":["A2","B1","B2"],"challenge":"Give one example.","difficulty":3,"context_tags":["work","study"],"teacher_note":"Good personal/work speaking.","student_support":"Explain why people misunderstand it.","language_targets":["explanation","wish"]},{"text":"If I had known that…, I would have…","levels":["B1","B2","C1"],"challenge":"Explain what you learned from it.","difficulty":4,"context_tags":["personal","reflection"],"teacher_note":"Third conditional naturally.","student_support":"Choose a decision, trip, purchase or work situation.","language_targets":["third-conditional","reflection"]},{"text":"A rule I used to believe in but now question is…","levels":["B2","C1"],"challenge":"Say whether any part of the old belief is still useful.","difficulty":5,"context_tags":["values","reflection"],"teacher_note":"Nuance.","student_support":"Explain what changed your view.","language_targets":["contrast","nuance"]}],"summary":"Open sentence stems that produce personal, spontaneous and grammatically rich answers.","favorite":true,"variants":["Real answers only.","Invented answers only.","Partner chooses the follow-up."],"group_size":"1–6","instructions":"Show an unfinished thought. Learner completes it, explains the answer and responds to one follow-up.","activity_type":"conversation","student_intro":"Complete the thought in a way that is true, interesting or convincing — then develop it.","student_steps":["Finish the sentence.","Explain the context.","Add an example or consequence.","Answer the follow-up."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["For me, it was when…","What changed my mind was…","Looking back…","The reason I say that is…"],"duration_minutes":15},{"tags":["depth","follow-up"],"goals":["depth","reasoning","extended speaking"],"title":"Five Whys","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Choose one thing you want to improve in your English.","levels":["A2","B1"],"challenge":"Reach a reason that is not simply ‘because English is useful’.","difficulty":2,"context_tags":["learning","personal"],"teacher_note":"Connect to concrete outcomes.","student_support":"Start with what. Then explain why it matters personally.","language_targets":["reasons","goals"]},{"text":"Choose one habit you would like to change.","levels":["A2","B1","B2"],"challenge":"Distinguish the immediate reason from the deeper reason.","difficulty":3,"context_tags":["daily-life","personal"],"teacher_note":"Avoid therapy framing; keep practical.","student_support":"Explain what makes the habit important.","language_targets":["reasoning","examples"]},{"text":"Choose one thing you think workplaces should change.","levels":["B1","B2"],"challenge":"At the fourth why, consider the employer’s perspective.","difficulty":3,"context_tags":["work"],"teacher_note":"Good work discussion.","student_support":"Move from complaint to underlying principle.","language_targets":["reasoning","perspective"]},{"text":"Choose one opinion you hold strongly about education or work.","levels":["B2","C1"],"challenge":"Your fifth answer must be more precise than your first, not just repeated.","difficulty":5,"context_tags":["education","work"],"teacher_note":"Use follow-up variants: what makes that matter / what would happen otherwise.","student_support":"Be ready to question your own assumptions.","language_targets":["critical-thinking","nuance"]}],"summary":"Keep asking why until a surface opinion becomes a more precise underlying reason.","favorite":false,"variants":["Learner asks the five whys to teacher.","Stop when an answer becomes concrete enough.","After five, learner summarizes the chain in one sentence."],"group_size":"1–2","instructions":"Start with one preference/opinion. Ask why repeatedly, but vary follow-up wording so it remains conversational.","activity_type":"conversation","student_intro":"Start with a simple answer. We’ll keep digging until the real reason becomes clearer.","student_steps":["Give your first answer.","Explain why it matters.","Go deeper without repeating yourself.","Summarize the underlying reason."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["The main reason is…","What matters to me is…","That’s connected to…","If I go deeper, I think…"],"duration_minutes":15},{"tags":["logic","questions"],"goals":["questions","hypothesis language","interaction"],"title":"Guess My Rule","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Some activities are IN my category, others are OUT. Discover the rule.","levels":["A2","B1"],"challenge":"Explain your rule before your final guess.","difficulty":2,"context_tags":["hobbies","logic"],"teacher_note":"Hidden rule: activities you can do alone and outdoors. IN: walking, running, photography. OUT: cinema, chess club, cooking at home.","student_support":"Ask: Is ___ in the category?","language_targets":["questions","hypothesis"]},{"text":"Discover which work messages I consider ‘urgent’.","levels":["B1","B2"],"challenge":"Define the rule precisely enough to predict a new example.","difficulty":3,"context_tags":["work","communication"],"teacher_note":"Hidden rule: blocks work today and needs action within two hours; importance alone is not enough.","student_support":"Test different situations.","language_targets":["clarification","definition"]},{"text":"Discover my rule for a ‘good travel destination’.","levels":["A2","B1","B2"],"challenge":"Propose a destination and predict whether it fits.","difficulty":3,"context_tags":["travel","preferences"],"teacher_note":"Hidden rule: walkable + good public transport + at least one nature option; price irrelevant.","student_support":"Ask about weather, crowds, cost, transport, activities.","language_targets":["questions","prediction"]},{"text":"Discover which business ideas pass my first filter.","levels":["B2","C1"],"challenge":"Formulate the rule as three criteria.","difficulty":5,"context_tags":["business","logic"],"teacher_note":"Hidden rule: recurring problem + clear buyer + can test cheaply; novelty not required.","student_support":"Test market, complexity, recurring demand, regulation and cost.","language_targets":["hypothesis","criteria"]}],"summary":"Infer a hidden category or rule by asking questions and testing examples.","favorite":false,"variants":["Learner invents the rule.","Limit to yes/no questions first, then open questions.","Require a confidence percentage before final guess."],"group_size":"1–6","instructions":"Teacher uses private rule. Learner proposes examples/questions and must state the rule only after collecting evidence.","activity_type":"speaking_game","student_intro":"There is a hidden rule. Ask smart questions, test examples and discover it.","student_steps":["Test an example.","Look for a pattern.","State a hypothesis.","Test it before your final answer."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["Would ___ count?","My theory is that…","If that’s true, then…","Let me test that with…"],"duration_minutes":15},{"tags":["work","conversation-management"],"goals":["interrupting","clarification","meeting language"],"title":"Interrupt Me Politely","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Interrupt because you missed one important detail.","levels":["B1","B2"],"challenge":"Do it without apologising excessively.","difficulty":3,"context_tags":["work","meeting"],"teacher_note":"Teacher monologue topic: project timeline with several dates.","student_support":"Stop me briefly and ask for clarification.","language_targets":["interrupting","clarification"]},{"text":"Interrupt because I am moving away from the main topic.","levels":["B1","B2","C1"],"challenge":"Use a phrase that protects rapport.","difficulty":4,"context_tags":["work","meeting"],"teacher_note":"Teacher deliberately digresses from meeting objective.","student_support":"Acknowledge, then redirect.","language_targets":["redirecting","interrupting"]},{"text":"Interrupt because one fact I just stated is incorrect.","levels":["B2","C1"],"challenge":"You are speaking to someone more senior.","difficulty":5,"context_tags":["work","hierarchy"],"teacher_note":"Power-sensitive correction.","student_support":"Correct me without sounding confrontational.","language_targets":["correction","register"]},{"text":"Interrupt because you need to leave in two minutes and a decision is still missing.","levels":["B1","B2"],"challenge":"Do not sound impatient.","difficulty":4,"context_tags":["work","time"],"teacher_note":"Meeting closure.","student_support":"Signal time pressure and move toward decision.","language_targets":["interrupting","decision"]}],"summary":"Practise entering a conversation, clarifying and redirecting without sounding abrupt.","favorite":true,"variants":["Teacher becomes harder to interrupt.","Learner must interrupt within ten seconds.","Replay with friend vs manager register."],"group_size":"1–2","instructions":"Teacher speaks for 20–40 seconds from the private scenario. Learner must interrupt at the specified moment/function.","activity_type":"roleplay","student_intro":"Real conversations overlap. Interrupt at the right moment without sounding rude.","student_steps":["Listen for the right moment.","Signal the interruption.","State what you need.","Return smoothly to the conversation."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["Sorry to jump in, but…","Can I just clarify one thing?","Before we move on…","If I could bring us back to…"],"duration_minutes":15},{"tags":["small-talk","confidence"],"goals":["follow-up questions","reacting","conversation management"],"title":"Keep It Going","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"A: I went to Florence last weekend.\nB: Oh really? …","levels":["A1","A2"],"challenge":"Keep it going for 6 turns without asking ‘And you?’","difficulty":1,"context_tags":["travel","small-talk"],"teacher_note":"Coach reaction chunks before question.","student_support":"React first, then ask something.","language_targets":["follow-up","reactions"]},{"text":"A: Work has been really busy lately.\nB: …","levels":["A2","B1"],"challenge":"Ask one question about feelings and one about facts.","difficulty":2,"context_tags":["work","small-talk"],"teacher_note":"Avoid interview mode.","student_support":"Show interest before changing topic.","language_targets":["reactions","follow-up"]},{"text":"A: I’ve started learning how to cook properly.\nB: …","levels":["A2","B1","B2"],"challenge":"After three turns, connect it to your own experience naturally.","difficulty":3,"context_tags":["hobbies","small-talk"],"teacher_note":"Teach self-disclosure balance.","student_support":"Use their answer to create the next question.","language_targets":["topic-development","self-disclosure"]},{"text":"A: I’m thinking about changing jobs.\nB: …","levels":["B1","B2"],"challenge":"Keep the conversation supportive without saying ‘You should’.","difficulty":3,"context_tags":["career","relationships"],"teacher_note":"Good for empathy and exploratory questions.","student_support":"Do not immediately give advice.","language_targets":["follow-up","empathy"]}],"summary":"Practice the skill of sustaining a conversation instead of giving isolated answers.","favorite":true,"variants":["Ban yes/no questions.","Require a reaction before every question.","Teacher intentionally gives short answers; learner rescues the exchange."],"group_size":"1–2","instructions":"Start from one short exchange. Learner must keep it alive for a target number of turns using reaction + follow-up.","activity_type":"conversation","student_intro":"Your goal is not to answer. Your goal is to keep the conversation alive.","student_steps":["React to what you heard.","Ask a connected question.","Use the answer to continue.","Avoid jumping to a new topic too quickly."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["Oh really?","That sounds…","How did that happen?","What was that like?","Speaking of that…"],"duration_minutes":15},{"tags":["softening","work","real-life"],"goals":["politeness","register","pragmatics"],"title":"Make It Less Direct","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"“Send me the file today.”","levels":["A2","B1"],"challenge":"Now make it urgent but still polite.","difficulty":2,"context_tags":["work","requests"],"teacher_note":"Could you send me the file today? / I’d really need it by…","student_support":"Make it a request, not an order.","language_targets":["requests","softening"]},{"text":"“I don’t like this idea.”","levels":["B1","B2"],"challenge":"Add one constructive alternative.","difficulty":3,"context_tags":["work","discussion"],"teacher_note":"I’m not sure this is the best approach because…","student_support":"Disagree with the idea, not the person.","language_targets":["disagreement","softening"]},{"text":"“You made a mistake.”","levels":["B1","B2","C1"],"challenge":"You are speaking to a client or senior colleague.","difficulty":4,"context_tags":["work","feedback"],"teacher_note":"It looks like there may be an issue with…","student_support":"Focus on the issue and evidence.","language_targets":["feedback","face-saving"]},{"text":"“Your price is too high.”","levels":["B1","B2","C1"],"challenge":"Ask what flexibility exists.","difficulty":4,"context_tags":["work","negotiation"],"teacher_note":"The current price is above what we had budgeted…","student_support":"Reject the current terms without closing the negotiation.","language_targets":["negotiation","softening"]}],"summary":"Soften overly direct English while preserving the speaker’s real intention.","favorite":true,"variants":["Friend vs client.","Soft → neutral → firm ladder.","Learner explains which words reduce force."],"group_size":"1–2","instructions":"Show a direct line. Learner produces a context-appropriate softer version, then roleplays the response.","activity_type":"fluency","student_intro":"Keep the message clear, but reduce unnecessary force.","student_steps":["Identify the core message.","Choose an appropriate softener.","Keep the request/opinion clear.","Continue the exchange."],"teacher_notes":null,"presenter_style":"repair","useful_language":["Could you…?","I’m not sure…","It looks like there may be…","Would there be any flexibility on…?"],"duration_minutes":15},{"tags":["assertiveness","work"],"goals":["assertiveness","clarity","register"],"title":"Make It More Direct","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"“Maybe it would be kind of useful if we could possibly finish this soon.”","levels":["B1","B2"],"challenge":"Keep one polite marker, remove the rest.","difficulty":3,"context_tags":["work","deadlines"],"teacher_note":"Could we finish this by Thursday?","student_support":"Say what you need and by when.","language_targets":["clarity","requests"]},{"text":"“I’m not completely sure this is exactly what we discussed.”","levels":["B1","B2"],"challenge":"Refer to the previous agreement.","difficulty":3,"context_tags":["work","agreement"],"teacher_note":"This is different from what we agreed on…","student_support":"If you know it differs, say so clearly.","language_targets":["assertiveness","clarification"]},{"text":"“I was just wondering if maybe there is any chance of looking at the salary at some point.”","levels":["B2","C1"],"challenge":"Sound confident without demanding an immediate yes.","difficulty":4,"context_tags":["work","career"],"teacher_note":"I’d like to discuss my salary / compensation review.","student_support":"Ask directly for the conversation you want.","language_targets":["assertiveness","negotiation"]},{"text":"“It might be helpful if communication improved a little.”","levels":["B2","C1"],"challenge":"Turn it into actionable feedback.","difficulty":4,"context_tags":["work","feedback"],"teacher_note":"We need project changes documented in the shared channel by…","student_support":"Name the behaviour and requested change.","language_targets":["feedback","specificity"]}],"summary":"Turn vague, hesitant or over-softened language into clear and professional communication.","favorite":true,"variants":["Remove one hedge at a time.","Compare clear vs rude.","Add a deadline/outcome to every rewrite."],"group_size":"1–2","instructions":"Show an overly vague line. Learner makes it clearer without becoming aggressive, then states the desired outcome.","activity_type":"fluency","student_intro":"Polite does not have to mean vague. Make the message clear enough to act on.","student_steps":["Find the real message.","Remove unnecessary hedging.","State the desired action.","Check that the tone remains respectful."],"teacher_notes":null,"presenter_style":"repair","useful_language":["I’d like to…","What I need is…","To be clear…","We agreed that…","Could we decide this by…?"],"duration_minutes":15},{"tags":["vocabulary","specificity"],"goals":["precision","description","extended answers"],"title":"Make It More Specific","levels":["A1","A2","B1","B2","C1"],"status":"active","prompts":[{"text":"My weekend was nice.","levels":["A1","A2"],"challenge":"Replace ‘nice’ completely.","difficulty":1,"context_tags":["daily-life","personal"],"teacher_note":"A1 scaffolding okay.","student_support":"Where? With who? What did you do? What made it enjoyable?","language_targets":["description","past-simple"]},{"text":"My job is stressful.","levels":["A2","B1"],"challenge":"Give one concrete example from a typical day.","difficulty":2,"context_tags":["work"],"teacher_note":"Move adjective → causes/evidence.","student_support":"What exactly causes the stress? When? What happens?","language_targets":["specificity","examples"]},{"text":"The trip was bad.","levels":["A2","B1","B2"],"challenge":"Describe it without using bad, terrible or awful.","difficulty":3,"context_tags":["travel"],"teacher_note":"Lexical range.","student_support":"Separate transport, accommodation, people and expectations.","language_targets":["description","precision"]},{"text":"Communication in our team could be better.","levels":["B1","B2","C1"],"challenge":"Turn it into actionable feedback.","difficulty":4,"context_tags":["work","team"],"teacher_note":"Business specificity.","student_support":"Identify behaviour, consequence and desired change.","language_targets":["feedback","specificity"]}],"summary":"Turn vague English into concrete, informative language that creates a real conversation.","favorite":true,"variants":["Ban common adjectives.","Add a number/example to every answer.","Teacher says ‘more specific’ until answer becomes concrete."],"group_size":"1–2","instructions":"Show a vague sentence. Learner upgrades it by adding observable details, examples, reasons or stronger vocabulary.","activity_type":"fluency","student_intro":"The sentence is understandable but vague. Make it concrete enough that another person can picture the situation.","student_steps":["Identify the vague part.","Add a concrete detail.","Give an example.","Choose more precise language."],"teacher_notes":null,"presenter_style":"repair","useful_language":["More specifically…","What I mean is…","For example…","The part that really… is…"],"duration_minutes":15},{"tags":["reformulation","real-life"],"goals":["natural English","chunks","register"],"title":"Make It Sound Like a Person","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"I very like this place.","levels":["A2"],"challenge":"Say it in a more enthusiastic way too.","teacher_note":"Target: I really like / I love this place.","student_support":"Make it natural without changing the meaning."},{"text":"I am agree with you.","levels":["A2","B1"],"challenge":"Now disagree politely instead.","teacher_note":"Target: I agree with you.","student_support":"Keep the same meaning."},{"text":"I want to know if you received my email.","levels":["B1","B2"],"challenge":"Make it sound warmer, then more direct.","teacher_note":"Possible: I just wanted to check whether you received…","student_support":"Imagine this is a polite work follow-up."},{"text":"For me it is not a problem.","levels":["B1","B2"],"challenge":"Give one professional alternative.","teacher_note":"Depends on intent: That’s fine with me / I don’t mind / No problem on my end.","student_support":"Choose a natural phrase for a casual conversation."},{"text":"This solution is not convenient for us.","levels":["B2","C1"],"challenge":"Soften it without becoming vague.","teacher_note":"Possible: This option wouldn’t really work for us / may not be the best fit.","student_support":"Imagine a business negotiation."}],"summary":"Upgrade textbook English into something a real person would naturally say.","favorite":true,"variants":["Register ladder: casual → neutral → professional.","No translation round: explain why the original feels unnatural in English.","Chunk capture: save the best reformulation to the learner bank."],"group_size":"1–2","instructions":"Show a technically understandable but unnatural line. The learner makes it sound natural, then uses the upgraded version in context.","activity_type":"fluency","student_intro":"Make the sentence sound like something a real person would naturally say.","student_steps":["Read the original.","Say a more natural version.","Explain what changed.","Use it in a short conversation."],"teacher_notes":null,"presenter_style":"repair","useful_language":["A more natural way to say it is…","I’d probably say…","That sounds a little too…","In a work context, I’d use…"],"duration_minutes":15},{"tags":["roleplay","micro"],"goals":["functional language","confidence","spontaneous speaking"],"title":"Micro Roleplay","levels":["A1","A2","B1","B2","C1"],"status":"active","prompts":[{"text":"You bought a shirt yesterday. It is the wrong size. Ask to exchange it.","levels":["A1","A2"],"challenge":"They do not have your size.","difficulty":1,"context_tags":["shopping","service"],"teacher_note":"Basic shop return language.","student_support":"Say what happened and what you want.","language_targets":["requests","returns"]},{"text":"A friend invites you somewhere you do not want to go. Decline without inventing a dramatic excuse.","levels":["A2","B1"],"challenge":"They ask you again.","difficulty":2,"context_tags":["social","plans"],"teacher_note":"Refusal + boundary.","student_support":"Be warm and clear.","language_targets":["refusals","politeness"]},{"text":"A colleague misunderstood your message and completed the wrong task. Clarify what you meant.","levels":["B1","B2"],"challenge":"Agree on the next action.","difficulty":3,"context_tags":["work","communication"],"teacher_note":"Work repair.","student_support":"Correct the misunderstanding without blaming.","language_targets":["clarification","repair"]},{"text":"A client wants a deadline you cannot realistically meet. Negotiate a new one.","levels":["B2","C1"],"challenge":"Client says delay is unacceptable.","difficulty":5,"context_tags":["work","client"],"teacher_note":"Negotiation and alternatives.","student_support":"Protect quality and relationship while being clear.","language_targets":["negotiation","deadlines"]}],"summary":"Short 60–90 second roleplays focused on one real communicative objective.","favorite":true,"variants":["Replay immediately after feedback.","Change relationship but keep objective.","30-second ultra-micro version."],"group_size":"1–2","instructions":"Run compact scenarios with one objective. Stop after outcome, give one correction, replay quickly.","activity_type":"roleplay","student_intro":"One situation. One objective. Get the result in about a minute.","student_steps":["Understand your objective.","Open naturally.","React to the other person.","Reach an outcome."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["I was hoping to…","I’m afraid I can’t…","I think there’s been a misunderstanding.","What I can offer is…"],"duration_minutes":18},{"tags":["low prep","conversation","chunks"],"goals":["fluency","vocabulary","justifying opinions"],"title":"Odd One Out — Conversation Edition","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"deadline · schedule · postpone · exhausted","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"convincing · awkward · persuasive · believable","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"bring up · point out · run into · mention","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"budget · afford · expensive · negotiate","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"apologise · admit · deny · confess","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Quattro parole o idee: scegli l’intruso, ma la parte importante è difendere la scelta e contestare quella dell’altro.","favorite":true,"variants":["A2: usa categorie più concrete e dai una frase-starter: “I think ___ is different because…”","C1: richiedi una seconda interpretazione e una controargomentazione.","Vocabulary focus: dopo ogni set, fai creare una frase naturale con due elementi non scelti."],"group_size":"1–4","instructions":"Mostra un set alla volta. Lo studente sceglie l’intruso e deve giustificare la risposta con almeno due frasi. Se esistono più interpretazioni plausibili, sfruttale: chiedi “Could another answer work?” e fai difendere una seconda scelta.","activity_type":"speaking_game","student_intro":"Choose the odd one out. There may be more than one possible answer — the important part is how you justify your choice.","student_steps":["Choose one item.","Explain why it is different.","Listen to a challenge or alternative answer.","Defend your choice or change your mind."],"teacher_notes":"Evita set con una sola risposta puramente grammaticale: deve generare discussione.","presenter_style":"odd_one_out","useful_language":["I’d say ___ is the odd one out because…","The others all have something in common: …","Another possible answer could be…","I see your point, but…"],"duration_minutes":12},{"tags":["personalisation","detective"],"goals":["storytelling","questions","interaction"],"title":"One Detail Is False","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"A memorable trip: tell three details. One must be false.","levels":["A2","B1"],"challenge":"Make the false detail believable.","difficulty":2,"context_tags":["travel","personal"],"teacher_note":"Encourage connected narrative, not isolated facts.","student_support":"Include place, event and person.","language_targets":["past-simple","questions"]},{"text":"Your first or worst job: three details, one false.","levels":["B1","B2"],"challenge":"Answer three follow-up questions without revealing the lie.","difficulty":3,"context_tags":["work","personal"],"teacher_note":"Good for workplace vocabulary.","student_support":"Include something about people, tasks and a surprising moment.","language_targets":["past-tenses","follow-up"]},{"text":"A skill you learned: three details, one false.","levels":["A2","B1","B2"],"challenge":"The listener gets only four questions.","difficulty":2,"context_tags":["learning","personal"],"teacher_note":"Use process language.","student_support":"Say why, how and what was difficult.","language_targets":["storytelling","questions"]},{"text":"A strange thing that happened to you: three details, one false.","levels":["B1","B2"],"challenge":"Add one irrelevant true detail to make detection harder.","difficulty":3,"context_tags":["personal","story"],"teacher_note":"Push narrative cohesion.","student_support":"Create a coherent mini-story.","language_targets":["narrative","interaction"]}],"summary":"Tell a short story containing one invented detail while the other person investigates.","favorite":false,"variants":["Teacher goes first.","Two truths and one lie but all details must belong to one story.","Listener must explain evidence before guessing."],"group_size":"2–6","instructions":"Learner chooses a topic, tells three connected details, one false. Other person must uncover it through follow-up questions.","activity_type":"speaking_game","student_intro":"Tell the story convincingly. One detail is false — but do not make it obvious.","student_steps":["Choose your three details.","Tell them as one story.","Answer follow-up questions.","Let the listener guess."],"teacher_notes":null,"presenter_style":"story","useful_language":["What happened next?","Are you sure that…?","That sounds believable because…","I think the false detail is…"],"duration_minutes":15},{"tags":["timed","warmup"],"goals":["fluency","confidence","extended answers"],"title":"One Minute, No Escape","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"A habit you would like to change","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Something people spend too much money on","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A place you could happily visit again","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A skill everybody should learn","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A small thing that can ruin your day","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Something you used to believe but changed your mind about","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Un minuto di parlato continuo su un tema semplice, con follow-up che impediscono risposte preparate.","favorite":true,"variants":["A2: 30 secondi e tre parole-guida.","B2/C1: vieta tre parole troppo facili prima di iniziare.","Second round: stesso tema, ma lo studente deve includere due nuovi chunks."],"group_size":"1–4","instructions":"Dai 15 secondi per pensare. Lo studente parla per 60 secondi senza fermarsi. Tu non correggi durante il minuto. Alla fine scegli solo 1–2 upgrade linguistici e fai un secondo mini-round di 30 secondi.","activity_type":"fluency","student_intro":null,"student_steps":[],"teacher_notes":"Perfetto come apertura lezione per misurare scioltezza senza farlo sembrare un test.","presenter_style":"prompt","useful_language":[],"duration_minutes":10},{"tags":["personalisation","confidence"],"goals":["personalisation","extended answers","fluency"],"title":"Personalise It","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"People often feel nervous before important events.","levels":["A1","A2"],"challenge":"Say what you do before it.","difficulty":1,"context_tags":["personal","emotions"],"teacher_note":"Simple personalisation.","student_support":"Think of an event that makes you nervous.","language_targets":["present-simple","examples"]},{"text":"Many people find it difficult to keep healthy routines.","levels":["A2","B1"],"challenge":"Give one realistic change you could make.","difficulty":2,"context_tags":["daily-life","habits"],"teacher_note":"Keep non-medical/general.","student_support":"Say which routine is easy or difficult for you and why.","language_targets":["habits","personalisation"]},{"text":"People sometimes stay in jobs they no longer enjoy.","levels":["B1","B2"],"challenge":"Give two reasons someone might stay.","difficulty":3,"context_tags":["work","career"],"teacher_note":"Perspective + personal example.","student_support":"Connect to something you have seen or experienced.","language_targets":["reasons","personalisation"]},{"text":"Technology changes the way people communicate.","levels":["A2","B1","B2"],"challenge":"Mention one improvement and one downside.","difficulty":3,"context_tags":["technology","communication"],"teacher_note":"Contrast language.","student_support":"Compare your communication now with five years ago.","language_targets":["comparison","examples"]}],"summary":"Turn generic textbook statements into personally meaningful speaking.","favorite":false,"variants":["Personal answer first, generalisation second.","Invent an example if learner prefers privacy.","Partner asks the follow-up."],"group_size":"1–4","instructions":"Show a generic statement. Learner connects it to their own experience, gives an example and asks/answers a follow-up.","activity_type":"conversation","student_intro":"The sentence is general. Make it about a real person: you, someone you know, or a believable example.","student_steps":["Connect it to experience.","Give a specific example.","Explain why it matters.","Develop the conversation."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["In my case…","That reminds me of…","I’ve noticed that…","A good example is…"],"duration_minutes":12},{"tags":["chunks","ranking","game"],"goals":["chunks","evaluation","natural English"],"title":"Phrase Auction","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"SITUATION: polite disagreement\nBUDGET: 3 phrases\n• I see your point, but…\n• You are wrong.\n• I’m not sure I’d agree.\n• In my opinion personally…\n• Another way of looking at it is…\n• No, because…","levels":["B1","B2"],"challenge":"Use all purchased phrases in a short discussion.","difficulty":3,"context_tags":["work","discussion"],"teacher_note":"Naturalness + register.","student_support":"Buy the phrases you would genuinely use.","language_targets":["chunks","disagreement"]},{"text":"SITUATION: asking for clarification\nBUDGET: 3 phrases\n• What do you mean?\n• Could you clarify what you mean by…?\n• I don’t understand you.\n• Just to make sure I’ve understood…\n• Can you repeat?\n• When you say…, do you mean…?","levels":["B1","B2"],"challenge":"Choose one phrase you would NOT buy and explain why.","difficulty":3,"context_tags":["work","conversation"],"teacher_note":"Not all weak phrases are ungrammatical.","student_support":"Consider different registers.","language_targets":["clarification","chunks"]},{"text":"SITUATION: professional follow-up\nBUDGET: 3 phrases\n• Just checking in on…\n• Why haven’t you replied?\n• I wanted to follow up on…\n• Any news?\n• When can I expect an update?\n• Please answer ASAP.","levels":["B1","B2","C1"],"challenge":"Build a three-line spoken follow-up using your purchases.","difficulty":4,"context_tags":["work","communication"],"teacher_note":"Register discussion.","student_support":"Balance warmth, clarity and urgency.","language_targets":["follow-up","register"]},{"text":"SITUATION: negotiating\nBUDGET: 3 phrases\n• Is there any flexibility on…?\n• That’s impossible.\n• What if we…?\n• We can’t accept that.\n• Could we meet somewhere in the middle?\n• Our position is…","levels":["B2","C1"],"challenge":"Handle one objection using only purchased phrases plus your own language.","difficulty":5,"context_tags":["work","negotiation"],"teacher_note":"Functional coverage.","student_support":"Choose a useful mix, not three identical functions.","language_targets":["negotiation","chunks"]}],"summary":"Spend a limited budget on the phrases that are most useful or natural for a situation, then prove the choices.","favorite":true,"variants":["Different prices for phrases.","Learners bid against each other.","One purchased phrase is removed before roleplay."],"group_size":"1–6","instructions":"Give six phrases and a budget. Learner ‘buys’ only three, explains value, then must use purchased phrases in a roleplay.","activity_type":"speaking_game","student_intro":"You cannot keep every phrase. Spend your budget on the language you think is most useful.","student_steps":["Read all options.","Choose your phrases.","Explain why they are worth buying.","Use them in context."],"teacher_notes":null,"presenter_style":"ranking","useful_language":["I’d spend my budget on…","This is more flexible because…","I wouldn’t choose ___ because…","This phrase works when…"],"duration_minutes":18},{"tags":["business","decisions"],"goals":["problem solving","decision language","comparison"],"title":"Problem → Options → Decision","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Your commute has become too expensive and takes 90 minutes each way.","levels":["B1","B2"],"challenge":"One option must be low-cost but inconvenient.","difficulty":3,"context_tags":["daily-life","transport"],"teacher_note":"Personal decision structure.","student_support":"Define the real problem before listing options.","language_targets":["options","comparison"]},{"text":"Your team has too many meetings and too little focus time.","levels":["B1","B2","C1"],"challenge":"Management refuses to reduce the total communication.","difficulty":4,"context_tags":["work","team"],"teacher_note":"Business problem solving.","student_support":"Generate at least three different interventions.","language_targets":["proposal","trade-offs"]},{"text":"A small business is getting more customers but service quality is dropping.","levels":["B2","C1"],"challenge":"There is no budget for a full-time hire.","difficulty":5,"context_tags":["business","service"],"teacher_note":"Prioritisation.","student_support":"Consider staffing, process, pricing and scope.","language_targets":["decision","trade-offs"]},{"text":"You have five free days but two very different travel ideas.","levels":["B1","B2"],"challenge":"Weather forecast changes for your preferred option.","difficulty":3,"context_tags":["travel","planning"],"teacher_note":"Decision language.","student_support":"Define criteria before choosing.","language_targets":["comparison","decision"]}],"summary":"Structure a decision by defining the problem, generating alternatives and choosing with reasons.","favorite":true,"variants":["Assign decision criteria first.","Partner challenges each option.","Final answer must include one risk."],"group_size":"1–4","instructions":"Learner must not jump straight to a solution. Require problem definition, three options, comparison and final decision.","activity_type":"conversation","student_intro":"Do not jump to the answer. Define the problem, create options, compare them, then decide.","student_steps":["Define the real problem.","Generate at least three options.","Compare costs and benefits.","Choose and justify."],"teacher_notes":null,"presenter_style":"ranking","useful_language":["The core problem is…","One option would be…","The advantage is…, whereas…","On balance, I’d choose…"],"duration_minutes":18},{"tags":["roleplay","real life"],"goals":["pragmatics","natural chunks","conversation repair"],"title":"Repair the Conversation","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"At work: “Give me the file today.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Small talk: “Why are you not married?”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Restaurant: “I want another table because this is bad.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Meeting: “You are wrong.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Email follow-up: “Why didn’t you answer me?”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Travel: “Tell me where the station is.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Improve awkward lines, then continue the interaction naturally.","favorite":true,"variants":["Register shift: casual, neutral, professional.","Use one chunk from the learner’s Word & Chunk Bank.","Pressure mode: five seconds to repair the line."],"group_size":"1–2","instructions":"Read the awkward line. Explain what sounds wrong, blunt or unnatural. Replace it, say it aloud, then continue for at least three turns.","activity_type":"speaking_game","student_intro":"The sentence may sound too direct, awkward or unnatural. Make it better and keep the conversation going.","student_steps":["Read the original line.","Make it sound more natural.","Say your improved version aloud.","Continue the conversation for at least three turns."],"teacher_notes":null,"presenter_style":"repair","useful_language":["Would you mind…?","Could you possibly…?","I’m not sure I agree.","I was wondering if…","Sorry to bother you, but…"],"duration_minutes":18},{"tags":["register","reformulation"],"goals":["register","chunks","flexibility"],"title":"Say It Three Ways","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Ask someone to wait for five minutes.","levels":["A2","B1"],"challenge":"Now make the professional version warmer.","difficulty":2,"context_tags":["daily-life","work"],"teacher_note":"Possible: Hang on a sec / Could you wait five minutes? / Would you mind giving me five minutes?","student_support":"Casual → neutral → professional.","language_targets":["requests","register"]},{"text":"Say that you cannot attend an event.","levels":["A2","B1","B2"],"challenge":"Add a short reason without over-explaining.","difficulty":3,"context_tags":["social","work"],"teacher_note":"Observe apology + refusal chunks.","student_support":"Friend → acquaintance → client.","language_targets":["refusals","register"]},{"text":"Tell someone you disagree with their idea.","levels":["B1","B2","C1"],"challenge":"Make the professional version firmer.","difficulty":4,"context_tags":["work","discussion"],"teacher_note":"Useful contrast between softening and vagueness.","student_support":"Friend → colleague → senior manager.","language_targets":["disagreement","register"]},{"text":"Ask for an update because something is late.","levels":["B1","B2","C1"],"challenge":"Now sound urgent without sounding aggressive.","difficulty":4,"context_tags":["work","deadlines"],"teacher_note":"Focus on checking/following-up chunks.","student_support":"Text message → normal work chat → formal email-style speech.","language_targets":["follow-up","register"]}],"summary":"Express the same message in casual, neutral and professional English.","favorite":true,"variants":["Teacher names the register only after learner speaks.","Rank versions from softest to strongest.","Reuse a learner’s own real-life sentence."],"group_size":"1–2","instructions":"Give one communicative intention. Learner produces three versions for different registers and explains the differences.","activity_type":"fluency","student_intro":"Same meaning, different relationship. Can you change the register without changing the message?","student_steps":["Understand the intention.","Say it casually.","Say it neutrally.","Say it professionally."],"teacher_notes":null,"presenter_style":"repair","useful_language":["Casually, I’d say…","A more neutral version is…","In a professional context…","To make it softer, I’d add…"],"duration_minutes":15},{"tags":["sales","creative"],"goals":["persuasion","functional language","improvisation"],"title":"Sell Me Something Useless","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Sell me a notebook that costs €80 and has no special technology.","levels":["B1","B2"],"challenge":"I say: “A normal notebook costs €3.”","teacher_note":"Push objection handling.","student_support":"Focus on design, durability, identity or experience."},{"text":"Sell a silent alarm clock to someone who sleeps very deeply.","levels":["B1","B2"],"challenge":"The customer is extremely sceptical.","teacher_note":"","student_support":"Invent a plausible benefit."},{"text":"Sell a one-day holiday package in your own city to a local resident.","levels":["B1","B2","C1"],"challenge":"They say they have already seen everything.","teacher_note":"Good for benefit framing.","student_support":"Create a new perspective on familiar places."},{"text":"Sell a premium pen to a company that has gone completely paperless.","levels":["B2","C1"],"challenge":"The buyer says the product contradicts company policy.","teacher_note":"C1: require reframing rather than feature listing.","student_support":"Find a symbolic, practical or social use."}],"summary":"Improvised persuasion with deliberately difficult products and audiences.","favorite":false,"variants":["Change the target audience halfway through.","Ban cheap adjectives like amazing and great.","Teacher raises one objection every 20 seconds."],"group_size":"1–4","instructions":"Give the learner a product and an audience. They have 60 seconds to make it sound worth buying.","activity_type":"debate","student_intro":"You have one minute to make an awkward product sound genuinely worth buying.","student_steps":["Understand the product and audience.","Choose the strongest benefit.","Make your pitch.","Handle the objection."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["What makes this different is…","The real benefit is…","I understand that concern, but…","This is designed for people who…"],"duration_minutes":15},{"tags":["improvisation"],"goals":["storytelling","past tenses","fluency"],"title":"Story Chain — But Something Changes","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"You wake up in a hotel room and don’t remember how you got there.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A stranger gives you an envelope and says: “Don’t open it here.”","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"You miss your train, and that turns out to be the best thing that happened all week.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Your phone receives a photo taken five minutes in the future.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Costruzione di una storia a turni con cambi improvvisi che costringono a reagire e collegare idee.","favorite":false,"variants":["Twists: “Someone is lying”, “The location suddenly changes”, “A phone call interrupts everything”, “One detail from the beginning becomes important”.","A2: usa solo past simple e sequencers.","B2+: richiedi almeno un flashback o una falsa pista."],"group_size":"1–6","instructions":"Iniziate con una frase. Ogni turno aggiunge 1–3 frasi. Ogni due turni pesca un cambiamento e incorporalo immediatamente senza ricominciare.","activity_type":"storytelling","student_intro":"Build the story together. Every new turn changes something, so listen carefully and adapt.","student_steps":["Continue the story for 2–4 sentences.","Keep the details already established.","Use the new twist.","At the end, retell the whole story in one minute."],"teacher_notes":null,"presenter_style":"story","useful_language":["At first…","While this was happening…","All of a sudden…","It turned out that…","In the end…"],"duration_minutes":15},{"tags":["conversation","scale","trade-offs"],"goals":["opinions","nuance","justification"],"title":"Take a Side","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Money matters ←→ Enjoying your job matters","levels":["A2","B1","B2"],"challenge":"What would move you two steps toward the other side?","difficulty":2,"context_tags":["work","values"],"teacher_note":"Push precise qualifiers: much more, slightly, depends on stage of life.","student_support":"Choose where you are on the line, not just one end.","language_targets":["comparatives","hedging"]},{"text":"Plan everything ←→ Be spontaneous","levels":["A2","B1"],"challenge":"Does your position change when other people depend on you?","difficulty":2,"context_tags":["daily-life","travel"],"teacher_note":"Useful for frequency/adverbs and examples.","student_support":"Think about travel, weekends and important events.","language_targets":["preferences","examples"]},{"text":"Be completely honest ←→ Protect someone’s feelings","levels":["B1","B2","C1"],"challenge":"Give one case where your normal position would be wrong.","difficulty":4,"context_tags":["relationships","work"],"teacher_note":"Good for nuance and conditionals.","student_support":"Think about friendship, work and difficult feedback.","language_targets":["hedging","conditionals"]},{"text":"Career stability ←→ Career growth","levels":["B1","B2","C1"],"challenge":"Now answer as if you had a family depending on your income.","difficulty":4,"context_tags":["work","career"],"teacher_note":"Push perspective shift.","student_support":"Think about money, learning and risk.","language_targets":["trade-offs","perspective"]}],"summary":"Place yourself between two opposing positions and explain exactly why you are there.","favorite":false,"variants":["Force a midpoint first, then make the learner move.","Add a new condition after the first answer.","Pairs: learners choose positions before hearing each other."],"group_size":"1–6","instructions":"Show a two-ended scale. The learner chooses a position, explains it, then reacts when one condition changes.","activity_type":"conversation","student_intro":"Choose where you stand between the two extremes. The interesting part is why you are there.","student_steps":["Choose a position.","Explain your reasons.","Give a real example.","React when the situation changes."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I’m closer to… because…","I’d put myself somewhere in the middle.","It depends mainly on…","I’d move toward the other side if…"],"duration_minutes":15},{"tags":["pragmatics","indirectness"],"goals":["pragmatics","inference","response"],"title":"Tell Me What I Mean","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"“That might be difficult.” — said by a manager after you ask for Friday off.","levels":["B1","B2"],"challenge":"Respond without forcing them to say yes/no.","difficulty":3,"context_tags":["work","requests"],"teacher_note":"Discuss soft refusal/constraint.","student_support":"Is it a maybe, a soft no, or a request for more information?","language_targets":["pragmatics","indirectness"]},{"text":"“I’ll think about it.” — said after you propose an expensive purchase.","levels":["B1","B2"],"challenge":"Ask one follow-up that sounds natural, not pushy.","difficulty":3,"context_tags":["shopping","decision"],"teacher_note":"Possible delay/soft refusal/genuine consideration.","student_support":"What could this mean depending on tone/context?","language_targets":["pragmatics","follow-up"]},{"text":"“That’s interesting.” — said after a controversial idea in a meeting.","levels":["B2","C1"],"challenge":"Respond in a way that invites a clearer opinion.","difficulty":4,"context_tags":["work","meeting"],"teacher_note":"Tone/context critical.","student_support":"It may be genuine or distancing.","language_targets":["pragmatics","clarification"]},{"text":"“We’ll need to revisit the numbers.” — said at the end of a negotiation.","levels":["B2","C1"],"challenge":"Respond by clarifying the next step.","difficulty":5,"context_tags":["work","negotiation"],"teacher_note":"Business implicature.","student_support":"What concern is likely hidden behind the phrase?","language_targets":["pragmatics","business"]}],"summary":"Interpret indirect or ambiguous language and respond to the intended meaning, not only the literal words.","favorite":true,"variants":["Give two contexts for the same line.","Learner performs two intonations with different meanings.","Rewrite indirect line into explicit meaning."],"group_size":"1–4","instructions":"Show an indirect line. Learner explains possible implied meanings, chooses the most likely in context, then responds appropriately.","activity_type":"fluency","student_intro":"The words are not always the whole message. What is the speaker probably trying to communicate?","student_steps":["Interpret the literal sentence.","Infer the likely intended meaning.","Explain the context clues.","Respond naturally."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["They probably mean that…","It sounds like a soft way of saying…","Depending on the tone…","I’d respond by asking…"],"duration_minutes":15},{"tags":["small-talk","conversation-repair"],"goals":["small talk","topic shifts","confidence"],"title":"The Awkward Silence","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"You are having coffee with a new colleague. You have already talked about work. Silence.","levels":["A2","B1"],"challenge":"Do not ask ‘What are your hobbies?’","difficulty":2,"context_tags":["work","small-talk"],"teacher_note":"Encourage contextual bridges.","student_support":"Use something around you, something they said earlier, or a light new topic.","language_targets":["topic-shift","questions"]},{"text":"You are at a dinner with your partner’s friends. You only know one person. Silence.","levels":["A2","B1","B2"],"challenge":"Bring another person into the conversation too.","difficulty":3,"context_tags":["social","small-talk"],"teacher_note":"Good for inclusive questions.","student_support":"Choose a safe shared-context topic.","language_targets":["topic-shift","inclusion"]},{"text":"You are waiting before an online meeting starts with a client you have met once. Silence.","levels":["B1","B2"],"challenge":"Avoid weather and ‘How are you?’","difficulty":3,"context_tags":["work","client"],"teacher_note":"Useful business small talk.","student_support":"Keep it professional but human.","language_targets":["small-talk","register"]},{"text":"You have just finished talking about your trip with a language exchange partner. Silence.","levels":["A2","B1"],"challenge":"Use ‘Speaking of…’ or another natural transition.","difficulty":2,"context_tags":["travel","social"],"teacher_note":"Topic chaining.","student_support":"Bridge from travel to another topic.","language_targets":["topic-shift","chunks"]}],"summary":"Recover a conversation when both people have run out of things to say.","favorite":false,"variants":["Teacher rates how natural the transition feels.","Give three possible rescue topics and rank them.","One minute with no direct question allowed."],"group_size":"1–2","instructions":"Show where the conversation stopped. Learner must restart it naturally without an abrupt unrelated question.","activity_type":"conversation","student_intro":"The conversation has stopped. Restart it without making the next question feel random.","student_steps":["Notice the shared context.","Choose a bridge.","Restart naturally.","Develop the new topic."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["Speaking of that…","That reminds me…","By the way…","I meant to ask you…"],"duration_minutes":12},{"tags":["questions","natural-English"],"goals":["question formation","pragmatics","conversation"],"title":"The Better Question","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"You meet a new colleague. Which sounds best?\nA) How long are you working here?\nB) How long have you worked here?\nC) Since when do you work here?","levels":["A2","B1"],"challenge":"Ask a natural follow-up after they answer.","difficulty":2,"context_tags":["work","small-talk"],"teacher_note":"Expected B; accept present perfect continuous if reformulated naturally.","student_support":"Think about a situation that started in the past and continues now.","language_targets":["present-perfect","questions"]},{"text":"A friend looks tired. Which sounds best?\nA) What happened to you?\nB) Are you okay? You look exhausted.\nC) Why are you like this?","levels":["A2","B1"],"challenge":"Continue for two more turns.","difficulty":2,"context_tags":["relationships","wellbeing"],"teacher_note":"B is safest/natural; discuss when A could work.","student_support":"Think about tone, not only grammar.","language_targets":["pragmatics","follow-up"]},{"text":"You need a deadline extension. Which opening is strongest?\nA) Can you move the deadline?\nB) I was wondering whether there might be any flexibility on the deadline.\nC) I need more time, okay?","levels":["B1","B2","C1"],"challenge":"Make option B slightly more direct without sounding rude.","difficulty":4,"context_tags":["work","requests"],"teacher_note":"Discuss power distance and urgency.","student_support":"Think about register and relationship.","language_targets":["politeness","register"]},{"text":"You disagree in a meeting. Which question opens discussion best?\nA) Don’t you think that’s wrong?\nB) What makes you confident that approach will work?\nC) Why would we do that?","levels":["B2","C1"],"challenge":"Make B softer, then firmer.","difficulty":4,"context_tags":["work","meetings"],"teacher_note":"Useful for pragmatic force.","student_support":"Aim for challenge without hostility.","language_targets":["disagreement","register"]}],"summary":"Choose the most natural question for a situation, then continue the conversation.","favorite":false,"variants":["Hide the options after selection and continue naturally.","Ask learner to improve the two weaker questions.","Switch register: friend / colleague / client."],"group_size":"1–4","instructions":"Show a situation plus three possible questions. More than one may be grammatical; learner chooses the most natural/appropriate and explains.","activity_type":"speaking_game","student_intro":"Several questions may be understandable. Choose the one that best fits the situation.","student_steps":["Read the situation.","Choose the strongest question.","Explain why.","Use it to continue the conversation."],"teacher_notes":null,"presenter_style":"choice","useful_language":["That one sounds more natural because…","It’s grammatically possible, but…","I’d make it softer by saying…","A natural follow-up would be…"],"duration_minutes":12},{"tags":["service","register"],"goals":["complaints","register","assertiveness"],"title":"The Complaint Ladder","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Your food is cold.","levels":["A2","B1"],"challenge":"The waiter says, ‘It’s supposed to be like that.’","difficulty":2,"context_tags":["restaurant","service"],"teacher_note":"Firmness should come from clarity, not aggression.","student_support":"Round 1: polite request. Round 2: firmer. Round 3: ask for a clear remedy.","language_targets":["complaints","register"]},{"text":"A delivery is five days late.","levels":["A2","B1","B2"],"challenge":"They give you another vague estimate.","difficulty":3,"context_tags":["shopping","service"],"teacher_note":"Deadline language.","student_support":"Ask for update → ask for commitment → request compensation/cancellation.","language_targets":["complaints","deadlines"]},{"text":"A contractor repeatedly misses agreed appointments.","levels":["B1","B2"],"challenge":"They blame scheduling problems outside their control.","difficulty":3,"context_tags":["services","home"],"teacher_note":"Assertiveness practice.","student_support":"Move from concern to boundary to consequence.","language_targets":["boundaries","complaints"]},{"text":"A supplier has failed the same quality check for the third time.","levels":["B2","C1"],"challenge":"They ask you to accept the batch ‘just this once’.","difficulty":5,"context_tags":["work","supplier"],"teacher_note":"Business escalation and conditions.","student_support":"Professional, factual, firm.","language_targets":["formal-complaint","conditions"]}],"summary":"Practise the same complaint at increasing levels of firmness without becoming rude.","favorite":true,"variants":["Learner labels each version 1–3 firmness.","Teacher makes the first version too aggressive; learner repairs it.","Compare spoken vs email-like wording."],"group_size":"1–2","instructions":"Use one problem for three rounds: polite, firm, final escalation. Discuss what linguistic changes create firmness.","activity_type":"roleplay","student_intro":"Say the same complaint three times: polite, firm, then very clear.","student_steps":["Start politely.","Make the request explicit.","Increase firmness without insulting.","State the outcome you need."],"teacher_notes":null,"presenter_style":"repair","useful_language":["I’m afraid there’s an issue with…","I do need this resolved today.","This is the third time this has happened.","If we can’t resolve this, I’ll need to…"],"duration_minutes":15},{"tags":["constraints","vocabulary"],"goals":["lexical range","precision","fluency"],"title":"The Forbidden Easy Word","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Describe your favourite place.\nFORBIDDEN: nice · good · beautiful","levels":["A2","B1"],"challenge":"Speak for 45 seconds.","difficulty":2,"context_tags":["places","personal"],"teacher_note":"Reward concrete description.","student_support":"Use atmosphere, details and what you can do there.","language_targets":["descriptive-vocabulary","fluency"]},{"text":"Describe a difficult day at work.\nFORBIDDEN: bad · busy · stressful","levels":["B1","B2"],"challenge":"Include one precise emotion and one work chunk.","difficulty":3,"context_tags":["work"],"teacher_note":"Good specificity exercise.","student_support":"Describe events and consequences instead of labels.","language_targets":["precision","storytelling"]},{"text":"Recommend a product or service.\nFORBIDDEN: good · useful · amazing · thing","levels":["A2","B1","B2"],"challenge":"Give one limitation too.","difficulty":3,"context_tags":["shopping","recommendations"],"teacher_note":"Benefit language.","student_support":"Focus on what it does and who it helps.","language_targets":["recommendations","lexical-range"]},{"text":"Evaluate a proposal.\nFORBIDDEN: good · bad · problem · interesting","levels":["B2","C1"],"challenge":"End with a qualified recommendation.","difficulty":4,"context_tags":["work","decision"],"teacher_note":"Advanced precision.","student_support":"Talk about feasibility, impact, risk and value.","language_targets":["evaluation","business-vocabulary"]}],"summary":"Force more precise vocabulary by banning overused easy words during a speaking task.","favorite":true,"variants":["Add one banned filler word.","Learner chooses the forbidden words for teacher.","Repeat after feedback with stricter bans."],"group_size":"1–6","instructions":"Give topic + banned words. Learner speaks for 45–60 seconds and must rephrase if a forbidden word appears.","activity_type":"vocabulary","student_intro":"Speak naturally, but the easy words on screen are unavailable.","student_steps":["Read the topic and bans.","Start speaking.","Rephrase if you hit a forbidden word.","Use concrete details instead."],"teacher_notes":null,"presenter_style":"taboo","useful_language":["What stands out is…","I’d describe it as…","The main advantage is…","The biggest drawback is…"],"duration_minutes":12},{"tags":["information gap"],"goals":["questions","interaction","clarification"],"title":"The Missing Detail","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"I arrived at work this morning and everyone looked at me.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I bought something yesterday and immediately regretted it.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"My friend cancelled our plans for a very strange reason.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I received an email that completely changed my week.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I was speaking English with someone and suddenly the conversation became much easier.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Domande naturali per ricostruire una situazione incompleta invece di rispondere passivamente.","favorite":false,"variants":["A2: fornisci starters: Why…? What happened…? Had you…?","B2: imponi almeno due follow-up questions prima di fare una nuova topic question.","Teacher swap: lo studente inventa il mistero e tu fai le domande."],"group_size":"1–2","instructions":"Leggi solo la situazione iniziale. Lo studente deve scoprire cosa è successo facendo domande. Tu puoi rispondere solo alle domande poste: non regalare informazioni.","activity_type":"conversation","student_intro":null,"student_steps":[],"teacher_notes":"Ottimo per studenti che sanno rispondere ma fanno poche domande.","presenter_style":"prompt","useful_language":[],"duration_minutes":12},{"tags":["questions","reverse task"],"goals":["question formation","interaction","conversation skills"],"title":"The Missing Question","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"ANSWER: About three times a week.","levels":["A1","A2"],"challenge":"Ask one follow-up question too.","teacher_note":"Possible: How often do you…? Many valid answers.","student_support":"Think: How often…?"},{"text":"ANSWER: Because I needed a change.","levels":["A2","B1"],"challenge":"Ask a question that makes this answer sound natural.","teacher_note":"Accept multiple contexts; focus on question grammar.","student_support":"Think about a past decision."},{"text":"ANSWER: I would, but only if I could work remotely.","levels":["B1","B2"],"challenge":"Ask a second question that explores the condition.","teacher_note":"Conditional question formation.","student_support":"Think about a hypothetical choice."},{"text":"ANSWER: Not exactly. It was more complicated than that.","levels":["B1","B2"],"challenge":"Create the original question and then continue the conversation.","teacher_note":"Good for repair and nuance.","student_support":"The previous question probably made an assumption."}],"summary":"Learners see an answer and must discover the most natural question that could have produced it.","favorite":true,"variants":["Give two possible questions for the same answer.","Teacher rejects the first question as unnatural; learner repairs it.","A1: provide the first question word."],"group_size":"1–4","instructions":"Show an answer. The learner invents the question, then asks one natural follow-up.","activity_type":"speaking_game","student_intro":"You get the answer first. Your job is to discover the question.","student_steps":["Read the answer.","Build a natural question.","Ask it aloud.","Add one follow-up."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["How often…?","Why did…?","Would you…?","What made you…?","How did…?"],"duration_minutes":12},{"tags":["conversation","unprepared"],"goals":["spontaneity","depth","follow-up"],"title":"The Unexpected Follow-Up","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"FIRST: What do you like doing at weekends?\nFOLLOW-UP: Which part of your weekend would you happily remove completely?","levels":["A2","B1"],"challenge":"Explain why.","difficulty":2,"context_tags":["daily-life","personal"],"teacher_note":"Avoid rehearsed hobby answer.","student_support":"The second question should make you rethink the first answer.","language_targets":["spontaneity","reasons"]},{"text":"FIRST: Do you enjoy travelling?\nFOLLOW-UP: What is something about travel that people pretend to enjoy more than they really do?","levels":["B1","B2"],"challenge":"Give a personal example.","difficulty":3,"context_tags":["travel","opinions"],"teacher_note":"Nuance.","student_support":"You can disagree with the premise.","language_targets":["spontaneity","opinion"]},{"text":"FIRST: What makes a good manager?\nFOLLOW-UP: Which positive leadership quality becomes dangerous when there is too much of it?","levels":["B1","B2","C1"],"challenge":"Give a workplace example.","difficulty":4,"context_tags":["work","leadership"],"teacher_note":"Depth.","student_support":"Think in terms of trade-offs.","language_targets":["nuance","examples"]},{"text":"FIRST: How important is confidence at work?\nFOLLOW-UP: When can sounding confident actually reduce trust?","levels":["B2","C1"],"challenge":"Give two different contexts.","difficulty":5,"context_tags":["work","communication"],"teacher_note":"Advanced pragmatics.","student_support":"Separate confidence from certainty.","language_targets":["nuance","critical-thinking"]}],"summary":"Move learners beyond rehearsed answers by adding a less predictable second question.","favorite":true,"variants":["Teacher writes follow-up based on learner’s answer.","Learner creates unexpected follow-up for teacher.","No planning time on second question."],"group_size":"1–2","instructions":"Ask the normal first question, then reveal the unexpected follow-up only after learner answers.","activity_type":"conversation","student_intro":"The first question is easy. The second one is designed to take you somewhere less rehearsed.","student_steps":["Answer the first question naturally.","Read the follow-up.","Think aloud if necessary.","Develop the new angle."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["I’ve never thought about that, but…","Actually, now that you mention it…","There’s one situation where…","I suppose the difference is…"],"duration_minutes":15},{"tags":["follow-up","small talk"],"goals":["interaction","questions","conversation skills"],"title":"Three Questions Deeper","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"What did you do this weekend?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What are you working on at the moment?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What kind of places do you enjoy visiting?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What is something you are looking forward to?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What makes a workday feel productive for you?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Qualunque risposta diventa conversazione: ogni risposta deve generare tre follow-up non ripetitivi.","favorite":false,"variants":["A2: mostra question stems: Why / How often / Who with / What happened next?","B2+: vieta di ripetere le stesse question words.","Reverse: lo studente conduce tutta la conversazione per tre minuti."],"group_size":"1–4","instructions":"Parti da una domanda comune. Dopo la risposta, l’interlocutore deve fare tre follow-up che vadano progressivamente più in profondità. Vietato cambiare subito argomento.","activity_type":"warmup","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":10},{"tags":["trade-offs","decisions"],"goals":["negotiation","comparatives","prioritisation"],"title":"Trade-Off","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Choose 3 for an apartment: cheap · central · large · quiet · modern","levels":["A2","B1"],"challenge":"Rent increases by 20% if you keep ‘central’.","difficulty":2,"context_tags":["housing","daily-life"],"teacher_note":"Comparatives/priorities.","student_support":"Rank what matters most to you.","language_targets":["comparatives","priorities"]},{"text":"Choose 3 in a job: high salary · flexible hours · interesting work · stability · fast promotion","levels":["A2","B1","B2"],"challenge":"One chosen benefit disappears after the first year.","difficulty":3,"context_tags":["work","career"],"teacher_note":"Personalise.","student_support":"Think about your life now, not an imaginary perfect person.","language_targets":["trade-offs","preferences"]},{"text":"Choose 3 for a team: speed · quality · low cost · creativity · predictability","levels":["B1","B2","C1"],"challenge":"A major client suddenly wants delivery one week earlier.","difficulty":4,"context_tags":["work","project"],"teacher_note":"Business prioritisation.","student_support":"Assume you cannot maximise all five.","language_targets":["negotiation","prioritisation"]},{"text":"Choose 3 when travelling: comfort · low price · flexibility · short travel time · authentic experience","levels":["A2","B1","B2"],"challenge":"You are travelling with someone whose priorities are opposite.","difficulty":3,"context_tags":["travel"],"teacher_note":"Good pair negotiation.","student_support":"Explain what you are willing to sacrifice.","language_targets":["compromise","preferences"]}],"summary":"Choose what to keep when not every desirable option can coexist.","favorite":true,"variants":["Pairs must agree on one shared selection.","Remove one choice after agreement.","Add a sixth option halfway through."],"group_size":"1–6","instructions":"Show five desirable features. Learner can keep only three and must negotiate or defend the selection.","activity_type":"speaking_game","student_intro":"You cannot have everything. Choose what matters most and defend the trade-off.","student_steps":["Choose three priorities.","Explain what you sacrificed.","Compare alternatives.","Adapt when the conditions change."],"teacher_notes":null,"presenter_style":"ranking","useful_language":["I’d prioritise… over…","I’m willing to give up…","The downside is…","That trade-off is worth it because…"],"duration_minutes":15},{"tags":["debate","fun"],"goals":["opinions","persuasion","spontaneity"],"title":"Unpopular Opinion","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Breakfast is overrated.","levels":["B1","B2"],"challenge":"I say: ‘It’s the most important meal of the day.’","difficulty":2,"context_tags":["food","daily-life"],"teacher_note":"Light, low-stakes.","student_support":"Give two reasons and one exception.","language_targets":["opinions","rebuttal"]},{"text":"Travelling is often more stressful than relaxing.","levels":["B1","B2"],"challenge":"Now explain why people still love it.","difficulty":3,"context_tags":["travel"],"teacher_note":"Balanced argument.","student_support":"Think about planning, money, transport and expectations.","language_targets":["concession","opinion"]},{"text":"Being extremely organised is not always a good thing.","levels":["B1","B2","C1"],"challenge":"Give a case where organisation is essential.","difficulty":3,"context_tags":["daily-life","work"],"teacher_note":"Nuance.","student_support":"Think about flexibility and control.","language_targets":["qualification","examples"]},{"text":"Networking is less useful than people claim.","levels":["B2","C1"],"challenge":"Defend networking for 20 seconds after your argument.","difficulty":4,"context_tags":["work","career"],"teacher_note":"Perspective shift.","student_support":"Distinguish authentic relationships from transactional networking.","language_targets":["argumentation","rebuttal"]}],"summary":"Defend a harmless contrarian opinion and handle follow-up challenges naturally.","favorite":false,"variants":["Learner invents the opinion.","Teacher assigns a position learner disagrees with.","Audience votes after each defence."],"group_size":"1–6","instructions":"Learner chooses or receives a low-stakes unpopular opinion and defends it. Keep topics non-sensitive and conversational.","activity_type":"debate","student_intro":"Defend an opinion that many people might disagree with — but keep it convincing, not provocative.","student_steps":["State the opinion clearly.","Give two reasons.","Handle the challenge.","Acknowledge one exception."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["I know this is unpopular, but…","My point is not that…, but that…","To be fair…","I’d still argue that…"],"duration_minutes":15},{"tags":["scaffolding","reformulation"],"goals":["extended answers","chunks","accuracy"],"title":"Upgrade That Answer","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"I like travelling.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"My job is stressful.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"I think social media is bad.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"I want to improve my English.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"The meeting was difficult.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Parti da una risposta piatta e trasformala in una risposta più naturale, precisa e personale.","favorite":true,"variants":["A2: usa schema answer + because + example.","B2+: aggiungi nuance o contrasto.","C1: cambia registro: casual → professional oppure neutral → persuasive."],"group_size":"1–3","instructions":"Mostra una risposta debole. Lo studente la migliora in tre passaggi: aggiungi dettaglio, aggiungi motivo/esempio, sostituisci almeno una parte con un chunk più naturale.","activity_type":"fluency","student_intro":null,"student_steps":[],"teacher_notes":"Molto utile quando lo studente dà risposte grammaticalmente corrette ma troppo povere.","presenter_style":"prompt","useful_language":[],"duration_minutes":15},{"tags":["chunks","vocabulary-bank"],"goals":["chunk activation","fluency","natural integration"],"title":"Use These 3 Chunks","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"TOPIC: planning a weekend\nCHUNKS: I’m thinking of… · it depends on… · in the end…","levels":["A2","B1"],"challenge":"Use them in a different order.","difficulty":2,"context_tags":["daily-life","plans"],"teacher_note":"Check chunk form, not just inclusion.","student_support":"Use the chunks as part of one answer, not three separate examples.","language_targets":["chunks","future-plans"]},{"text":"TOPIC: a work problem\nCHUNKS: bring up · work out · get back to someone","levels":["B1","B2"],"challenge":"Use one chunk in a question.","difficulty":3,"context_tags":["work","problem-solving"],"teacher_note":"Phrasal verb activation.","student_support":"Tell a mini-story about how the problem was handled.","language_targets":["phrasal-verbs","narrative"]},{"text":"TOPIC: disagreeing with a proposal\nCHUNKS: I see your point · the main concern is… · a better option might be…","levels":["B1","B2","C1"],"challenge":"Add one concession before your alternative.","difficulty":4,"context_tags":["work","meeting"],"teacher_note":"Functional chunk chain.","student_support":"Build a diplomatic disagreement.","language_targets":["disagreement","chunks"]},{"text":"TOPIC: explaining a change of mind\nCHUNKS: at first · the more I thought about it · I ended up…","levels":["B2","C1"],"challenge":"Add one contrast marker not shown.","difficulty":4,"context_tags":["reflection","personal"],"teacher_note":"Discourse chunks.","student_support":"Tell a coherent personal or invented story.","language_targets":["discourse-markers","storytelling"]}],"summary":"Integrate target chunks into real speaking without producing disconnected example sentences.","favorite":true,"variants":["Pull chunks from learner bank.","One chunk disappears after planning.","Teacher interrupts; learner must resume and still use remaining chunks."],"group_size":"1–2","instructions":"Show three chunks plus a speaking task. Learner must use all three naturally in one connected response or conversation.","activity_type":"vocabulary","student_intro":"Use all three chunks naturally in one connected piece of speaking.","student_steps":["Read the chunks.","Plan one coherent response.","Use each chunk naturally.","Keep meaning more important than ticking boxes."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["Try linking the chunks into one story.","You can change the tense if needed.","Use the chunk only where it fits naturally."],"duration_minutes":15},{"tags":["assumptions","advanced"],"goals":["critical thinking","nuance","argumentation"],"title":"What Are You Assuming?","levels":["B2","C1","C2"],"status":"active","prompts":[{"text":"‘If employees are productive at home, offices are unnecessary.’","levels":["B2","C1"],"challenge":"Find one role where the assumption clearly fails.","difficulty":4,"context_tags":["work","remote-work"],"teacher_note":"Do not debate claim first; identify assumptions first.","student_support":"What is being assumed about collaboration, culture and different roles?","language_targets":["assumptions","qualification"]},{"text":"‘People who really want to learn a language will always find the time.’","levels":["B2","C1"],"challenge":"Rephrase the claim so it becomes more defensible.","difficulty":4,"context_tags":["learning","life"],"teacher_note":"Good for absolute language.","student_support":"What is assumed about time, energy, money and responsibilities?","language_targets":["qualification","critical-thinking"]},{"text":"‘Higher prices mean better quality.’","levels":["B2","C1"],"challenge":"Give two contexts where price is a poor signal.","difficulty":4,"context_tags":["shopping","business"],"teacher_note":"Evidence vs heuristic.","student_support":"What relationship between price, brand and quality is assumed?","language_targets":["reasoning","examples"]},{"text":"‘A confident speaker is a competent professional.’","levels":["C1","C2"],"challenge":"Construct the strongest version of the claim before criticising it.","difficulty":5,"context_tags":["work","communication"],"teacher_note":"Steelman practice.","student_support":"Separate communication impression from actual expertise.","language_targets":["argumentation","nuance"]}],"summary":"Identify hidden assumptions inside ordinary claims and explore how conclusions change when they are challenged.","favorite":false,"variants":["Learner rewrites claim with qualifiers.","Separate assumption / evidence / conclusion.","Teacher defends the original claim after analysis."],"group_size":"1–4","instructions":"Show a claim. Learner identifies what must be assumed for it to be true, then tests the assumption with a counterexample.","activity_type":"debate","student_intro":"Before agreeing or disagreeing, identify what the statement quietly assumes.","student_steps":["Read the claim.","Name the hidden assumption.","Test it with an example.","Rewrite the claim more precisely."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["This assumes that…","That would only be true if…","A counterexample would be…","A more accurate version might be…"],"duration_minutes":18},{"tags":["creative","narration"],"goals":["storytelling","past tenses","inference"],"title":"What Happened Just Before?","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"You are standing outside a closed supermarket holding a birthday cake with your name on it.","levels":["A2","B1"],"challenge":"Add one surprising detail from ten minutes earlier.","teacher_note":"A2: scaffold past simple with first/then/after that.","student_support":"Who bought it? Why is the shop closed? Why are you there?"},{"text":"Your boss sends you a message saying: “Please do not explain this by email.”","levels":["B1","B2"],"challenge":"Include a misunderstanding.","teacher_note":"Good for reported speech and workplace chunks.","student_support":"What happened? What did you send? Why is email a problem?"},{"text":"You arrive home and there is a suitcase outside your door that is not yours.","levels":["A2","B1","B2"],"challenge":"The obvious explanation is wrong.","teacher_note":"","student_support":"Who could it belong to? How did it get there?"},{"text":"Everyone in the meeting suddenly becomes silent when you enter.","levels":["B1","B2"],"challenge":"Retell it from another person’s perspective.","teacher_note":"B2: push perspective and speculation.","student_support":"What were they talking about? Why does your arrival matter?"}],"summary":"Inference prompts that make learners build a plausible backstory from one strange moment.","favorite":false,"variants":["Reverse timeline: every new sentence moves further into the past.","Teacher adds one fact the learner must integrate.","Final retell: one-minute coherent story."],"group_size":"1–4","instructions":"Show the final scene only. The learner invents what happened immediately before it, then expands the story backwards.","activity_type":"storytelling","student_intro":"You only know the final moment. Build the story that led to it.","student_steps":["Study the scene.","Explain what happened just before.","Keep moving backwards.","Retell the full story in order."],"teacher_notes":null,"presenter_style":"story","useful_language":["Maybe…","It could have happened because…","Before that…","What probably happened was…"],"duration_minutes":15},{"tags":["roleplay","real-life"],"goals":["functional language","spontaneous speaking","pragmatics"],"title":"What Would You Say?","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"A waiter brings you the wrong order, but the restaurant is very busy.","levels":["A2","B1"],"challenge":"The waiter says your original order will take another 20 minutes.","difficulty":2,"context_tags":["restaurant","service"],"teacher_note":"Target polite complaint/request.","student_support":"Be clear and polite. Say what you ordered.","language_targets":["complaints","requests"]},{"text":"A colleague takes credit for an idea you suggested in yesterday’s meeting.","levels":["B1","B2","C1"],"challenge":"They say: ‘I thought we came up with it together.’","difficulty":4,"context_tags":["work","conflict"],"teacher_note":"Observe directness and face-saving.","student_support":"Choose whether to address it now, privately, or in writing.","language_targets":["assertiveness","clarification"]},{"text":"Your Airbnb is much noisier than the listing suggested and you cannot sleep.","levels":["A2","B1","B2"],"challenge":"The host says there is nothing they can do tonight.","difficulty":3,"context_tags":["travel","accommodation"],"teacher_note":"Push outcome request.","student_support":"Explain the problem and ask for a solution.","language_targets":["complaints","negotiation"]},{"text":"A friend repeatedly cancels plans at the last minute.","levels":["B1","B2"],"challenge":"They say they have simply been very busy.","difficulty":3,"context_tags":["relationships","conflict"],"teacher_note":"Good for boundaries and I-statements.","student_support":"Say how it affects you without attacking them.","language_targets":["boundaries","disagreement"]}],"summary":"Real-life situations with no model answer: the learner must react naturally on the spot.","favorite":true,"variants":["Give five seconds preparation only.","Replay the same situation more politely / more firmly.","Teacher changes attitude halfway through."],"group_size":"1–2","instructions":"Show one realistic situation. Learner responds immediately, then teacher plays the other person and extends the exchange.","activity_type":"roleplay","student_intro":"There is no script. React as naturally as you can.","student_steps":["Understand the situation.","Say what you would actually say.","Listen to the response.","Keep the conversation going."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["Excuse me, I think there’s been a mistake.","Could we find a way to…?","I wanted to bring something up.","I understand, but from my side…"],"duration_minutes":18},{"tags":["information-gap","questions"],"goals":["question formation","clarification","problem solving"],"title":"What''s the Problem?","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"A customer says: ‘It doesn’t work anymore.’ Find out what happened.","levels":["A2","B1"],"challenge":"You may ask only five questions.","difficulty":2,"context_tags":["service","technology"],"teacher_note":"Hidden context: wireless headphones stopped after phone update; Bluetooth was turned off.","student_support":"Ask what, when, where and what changed.","language_targets":["clarification","questions"]},{"text":"A colleague says: ‘The client is unhappy.’ Find out why.","levels":["B1","B2"],"challenge":"Ask one question about expectations, one about timing and one about communication.","difficulty":3,"context_tags":["work","client"],"teacher_note":"Hidden context: delivery was on time, but client expected a feature that was mentioned informally and never documented.","student_support":"Separate facts from assumptions.","language_targets":["clarification","root-cause"]},{"text":"A traveller says: ‘My booking has disappeared.’ Find out what the real issue is.","levels":["A2","B1","B2"],"challenge":"Solve it without immediately assuming the hotel made a mistake.","difficulty":3,"context_tags":["travel","hotel"],"teacher_note":"Hidden context: booking was made for the same date next month.","student_support":"Check date, name, platform and payment.","language_targets":["questions","problem-solving"]},{"text":"A team says productivity has suddenly dropped. Diagnose the most likely cause.","levels":["B2","C1"],"challenge":"Distinguish correlation from cause.","difficulty":5,"context_tags":["work","management"],"teacher_note":"Hidden context: new approval layer added two weeks ago creates a 24-hour wait on most tasks.","student_support":"Ask about process, workload, tools, incentives and recent changes.","language_targets":["diagnostic-questions","hypothesis"]}],"summary":"Ask targeted questions until enough information is available to diagnose the situation.","favorite":true,"variants":["Limit questions.","Require open questions only.","Learner summarizes the problem before proposing a solution."],"group_size":"1–4","instructions":"Learner sees only the symptom. Teacher uses the private note as the hidden answer and reveals information only when asked.","activity_type":"speaking_game","student_intro":"You do not have enough information yet. Ask the right questions before trying to solve the problem.","student_steps":["Clarify the symptom.","Ask focused questions.","Summarize what you know.","Identify the real problem."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["When did this start?","What changed just before that?","When you say ___, what exactly do you mean?","So, if I understand correctly…"],"duration_minutes":18},{"tags":["natural-English","reformulation"],"goals":["natural English","chunks","register"],"title":"Which One Sounds More Natural?","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"A) I very like it.\nB) I really like it.","levels":["A2"],"challenge":"Make the answer stronger without using very.","difficulty":1,"context_tags":["daily-life","language"],"teacher_note":"B. Then elicit I absolutely love it if appropriate.","student_support":"Which adverb position sounds natural?","language_targets":["adverb-position","natural-English"]},{"text":"A) It depends from the situation.\nB) It depends on the situation.","levels":["A2","B1"],"challenge":"Use depends on in a personal answer.","difficulty":2,"context_tags":["language","conversation"],"teacher_note":"B.","student_support":"Focus on the fixed preposition.","language_targets":["collocation","prepositions"]},{"text":"A) I’ll let you know as soon as I have an update.\nB) I’ll tell you when I will have news.","levels":["B1","B2"],"challenge":"Make A slightly more casual.","difficulty":3,"context_tags":["work","communication"],"teacher_note":"A.","student_support":"Think about natural future-time language.","language_targets":["future-time","chunks"]},{"text":"A) I don’t think that would work for us.\nB) For us, this solution is not convenient.","levels":["B1","B2","C1"],"challenge":"Make A firmer, then softer.","difficulty":4,"context_tags":["work","negotiation"],"teacher_note":"A generally more idiomatic for rejecting an option.","student_support":"Imagine a business discussion.","language_targets":["natural-English","register"]}],"summary":"Compare near-equivalent sentences and choose the version a real speaker is more likely to use.","favorite":true,"variants":["Hide labels and ask learner to rank.","Both can be correct: discuss register.","Learner repairs the weaker version."],"group_size":"1–4","instructions":"Show two or three alternatives. Learner chooses, explains, then creates a fresh sentence with the preferred chunk.","activity_type":"fluency","student_intro":"Both may be understandable. Choose the one that sounds more natural in this context.","student_steps":["Choose the stronger version.","Explain what sounds different.","Use the natural chunk.","Change the register if asked."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I’d be more likely to say…","That one sounds translated.","The natural chunk is…","In a more casual context…"],"duration_minutes":15},{"tags":["context","pragmatics"],"goals":["inference","register","roleplay"],"title":"Who Said It?","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"“Just leave it with me — I’ll sort it out.”\nWho is most likely speaking: a friend, a receptionist, or a manager?","levels":["A2","B1"],"challenge":"Create the previous line.","difficulty":2,"context_tags":["service","work","social"],"teacher_note":"Multiple plausible answers; reasoning matters.","student_support":"Think about tone and what ‘sort it out’ means.","language_targets":["inference","chunks"]},{"text":"“I’m afraid that’s not something we can approve at this stage.”\nWho might say this, and to whom?","levels":["B1","B2"],"challenge":"Reply professionally and ask what is possible.","difficulty":3,"context_tags":["work","formal"],"teacher_note":"Formal refusal.","student_support":"Think about formality and power.","language_targets":["register","refusal"]},{"text":"“You didn’t have to do that.”\nWhat are three different situations where this could mean different things?","levels":["B1","B2"],"challenge":"Perform two versions with different meaning.","difficulty":4,"context_tags":["social","pragmatics"],"teacher_note":"Pragmatics/intonation.","student_support":"It could express gratitude, surprise or criticism depending on tone.","language_targets":["intonation","meaning"]},{"text":"“That’s one way of looking at it.”\nWho might say it and what could they really mean?","levels":["B2","C1"],"challenge":"Respond as if you noticed the hidden disagreement.","difficulty":5,"context_tags":["work","discussion"],"teacher_note":"Implicature.","student_support":"Think about indirect disagreement.","language_targets":["pragmatics","indirectness"]}],"summary":"Infer speaker, relationship and context from one line, then improvise what came before and after.","favorite":true,"variants":["No options: infer freely.","Perform tone first, explain after.","Create two contexts for same line."],"group_size":"1–4","instructions":"Show a line with possible speakers/contexts. Learner chooses, explains clues, then performs a short continuation.","activity_type":"speaking_game","student_intro":"One line can reveal a lot. Work out who might be speaking and what is really happening.","student_steps":["Read the line.","Infer the relationship/context.","Explain the clues.","Continue the dialogue."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["It sounds like…","The phrase ___ suggests…","Depending on the tone…","I imagine the previous line was…"],"duration_minutes":15},{"tags":["zero prep","decision making"],"goals":["fluency","opinions","conditionals"],"title":"Would You Rather — No Easy Answers","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Would you rather have a job you love with an average salary, or a boring job that pays extremely well?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather always arrive 30 minutes early or 10 minutes late?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather live abroad for five years without your family or stay home and turn down your dream opportunity?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather be excellent at speaking English but weak at writing, or the opposite?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather work with a brilliant but difficult boss or a kind but disorganised one?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Scelte scomode o realistiche che obbligano a spiegare priorità, conseguenze e compromessi.","favorite":true,"variants":["A2: limita la risposta a choice + because + one example.","B2+: chiedi “What would make you switch sides?”","Work version: usa solo dilemmi professionali."],"group_size":"1–6","instructions":"Leggi una scelta. Lo studente deve scegliere subito, poi spiegare perché. Dopo la prima risposta aggiungi sempre una complicazione o chiedi cosa potrebbe fargli cambiare idea.","activity_type":"conversation","student_intro":"Choose one option. There is no perfect answer, so explain what matters most to you.","student_steps":["Make your choice.","Give at least two reasons.","React to one follow-up question.","Say what could make you change your mind."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I’d rather… because…","The main reason is…","It would depend on…","I might change my mind if…"],"duration_minutes":15},{"tags":["timer","warm-up"],"goals":["fluency","retrieval","confidence"],"title":"You Have 30 Seconds","levels":["A1","A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Recommend one place in your city to a visitor.","levels":["A1","A2"],"challenge":"Do not stop for 30 seconds.","difficulty":1,"context_tags":["travel","local-life"],"teacher_note":"Ignore minor errors; focus on continuity.","student_support":"Say what it is, why you like it and what to do there.","language_targets":["recommendations","fluency"]},{"text":"Explain one small habit that makes your day easier.","levels":["A2","B1"],"challenge":"Use at least one example.","difficulty":2,"context_tags":["daily-life"],"teacher_note":"Good warm-up.","student_support":"What is it? When do you do it? Why does it help?","language_targets":["explanation","fluency"]},{"text":"Convince me to try something you enjoy.","levels":["B1","B2"],"challenge":"No ‘good’, ‘nice’ or ‘amazing’.","difficulty":3,"context_tags":["hobbies","persuasion"],"teacher_note":"Lexical precision.","student_support":"Give benefit + example + answer one objection.","language_targets":["persuasion","descriptive-language"]},{"text":"Explain a complicated idea from your work in simple English.","levels":["B2","C1"],"challenge":"No specialist term unless you explain it immediately.","difficulty":4,"context_tags":["work","expertise"],"teacher_note":"Excellent for expert learners.","student_support":"Imagine I know nothing about your field.","language_targets":["plain-English","explanation"]}],"summary":"Fast speaking rounds that train immediate language retrieval under light pressure.","favorite":true,"variants":["20/40/60-second rounds.","Repeat same prompt and improve second attempt.","Teacher counts fillers, then learner tries again."],"group_size":"1–6","instructions":"Give 30 seconds preparation or none, depending on level. Learner speaks continuously until time ends.","activity_type":"warmup","student_intro":"You have 30 seconds. Keep speaking until the timer ends.","student_steps":["Understand the task.","Start quickly.","Add reasons or examples.","Keep going even if you need to rephrase."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["The main reason is…","For example…","What I mean is…","Another thing is…"],"duration_minutes":10}]'::jsonb);

with seed as (
  select value as row
  from speaking_activity_seed, jsonb_array_elements(payload)
)
update public.admin_speaking_activities activity
set
  summary = seed.row ->> 'summary',
  activity_type = seed.row ->> 'activity_type',
  levels = array(select jsonb_array_elements_text(seed.row -> 'levels')),
  goals = array(select jsonb_array_elements_text(seed.row -> 'goals')),
  tags = array(select jsonb_array_elements_text(seed.row -> 'tags')),
  duration_minutes = nullif(seed.row ->> 'duration_minutes','')::integer,
  group_size = seed.row ->> 'group_size',
  instructions = coalesce(seed.row ->> 'instructions',''),
  prompts = coalesce(seed.row -> 'prompts','[]'::jsonb),
  variants = coalesce(seed.row -> 'variants','[]'::jsonb),
  teacher_notes = nullif(seed.row ->> 'teacher_notes',''),
  favorite = coalesce((seed.row ->> 'favorite')::boolean,false),
  status = coalesce(seed.row ->> 'status','active'),
  student_intro = seed.row ->> 'student_intro',
  student_steps = coalesce(seed.row -> 'student_steps','[]'::jsonb),
  useful_language = coalesce(seed.row -> 'useful_language','[]'::jsonb),
  presenter_style = coalesce(seed.row ->> 'presenter_style','prompt'),
  updated_at = now()
from seed
where lower(activity.title) = lower(seed.row ->> 'title');

with seed as (
  select value as row
  from speaking_activity_seed, jsonb_array_elements(payload)
)
insert into public.admin_speaking_activities (
  title, summary, activity_type, levels, goals, tags, duration_minutes, group_size,
  instructions, prompts, variants, teacher_notes, favorite, status,
  student_intro, student_steps, useful_language, presenter_style
)
select
  seed.row ->> 'title',
  seed.row ->> 'summary',
  seed.row ->> 'activity_type',
  array(select jsonb_array_elements_text(seed.row -> 'levels')),
  array(select jsonb_array_elements_text(seed.row -> 'goals')),
  array(select jsonb_array_elements_text(seed.row -> 'tags')),
  nullif(seed.row ->> 'duration_minutes','')::integer,
  seed.row ->> 'group_size',
  coalesce(seed.row ->> 'instructions',''),
  coalesce(seed.row -> 'prompts','[]'::jsonb),
  coalesce(seed.row -> 'variants','[]'::jsonb),
  nullif(seed.row ->> 'teacher_notes',''),
  coalesce((seed.row ->> 'favorite')::boolean,false),
  coalesce(seed.row ->> 'status','active'),
  seed.row ->> 'student_intro',
  coalesce(seed.row -> 'student_steps','[]'::jsonb),
  coalesce(seed.row -> 'useful_language','[]'::jsonb),
  coalesce(seed.row ->> 'presenter_style','prompt')
from seed
where not exists (
  select 1 from public.admin_speaking_activities existing
  where lower(existing.title) = lower(seed.row ->> 'title')
);

drop table if exists speaking_activity_seed;

notify pgrst, 'reload schema';
